  ('npa-practice-2026-10-28-v1', '2008', 1, 1, ARRAY['the Constitution']::text[], '[{"key":"a1","display":"the Constitution","aliases":["Constitution"]}]'::jsonb, '[["Declaration of Independence"],["Articles of Confederation"],["Federalist Papers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution, not the Declaration, Confederation-era Articles, or ratification essays, is the supreme law.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 2, 1, ARRAY['sets up the government', 'defines the government', 'protects basic rights of Americans']::text[], '[{"key":"a1","display":"sets up the government","aliases":[]},{"key":"a2","display":"defines the government","aliases":[]},{"key":"a3","display":"protects basic rights of Americans","aliases":[]}]'::jsonb, '[["It appoints state governors"],["It sets the federal income-tax filing date"],["It elects the President directly"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution establishes and defines the federal government and protects basic rights. The distractors assign it unrelated operational tasks; it does not appoint state governors, set the annual tax filing date, or directly elect the President.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 3, 1, ARRAY['We the People']::text[], '[{"key":"a1","display":"We the People","aliases":[]}]'::jsonb, '[["Life, Liberty, and the pursuit of Happiness"],["Four score and seven years ago"],["In God We Trust"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'None of the quotations is the Constitution’s first three words, which are “We the People.”', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 4, 1, ARRAY['a change (to the Constitution)', 'an addition (to the Constitution)']::text[], '[{"key":"a1","display":"a change (to the Constitution)","aliases":["a change","a change to the Constitution","change (to the Constitution)"]},{"key":"a2","display":"an addition (to the Constitution)","aliases":["an addition","addition (to the Constitution)","an addition to the Constitution"]}]'::jsonb, '[["A court ruling that changes one case"],["A presidential executive order"],["A statute passed by Congress"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'An amendment changes or adds to the Constitution. A court ruling, executive order, and ordinary statute may affect government but none is an amendment to the Constitution.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 5, 1, ARRAY['the Bill of Rights']::text[], '[{"key":"a1","display":"the Bill of Rights","aliases":["Bill of Rights"]}]'::jsonb, '[["Articles of Confederation"],["Federalist Papers"],["Declaration of Independence"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The first ten constitutional amendments are called the Bill of Rights; the alternatives are separate founding documents.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 6, 1, ARRAY['speech', 'religion', 'assembly', 'press', 'petition the government']::text[], '[{"key":"speech","display":"speech","aliases":["freedom of speech","freedom of expression"]},{"key":"religion","display":"religion","aliases":["freedom of religion"]},{"key":"assembly","display":"assembly","aliases":["freedom of assembly"]},{"key":"press","display":"press","aliases":["freedom of the press","freedom of press"]},{"key":"petition","display":"petition the government","aliases":["freedom to petition the government"]}]'::jsonb, '[["A right to establish an official national religion"],["A ban on peaceful criticism of government"],["A ban on peaceful assembly"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The First Amendment protects religion, speech, press, assembly, and petition. Requiring a national religion or suppressing peaceful speech or assembly reverses those protections.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 7, 1, ARRAY['twenty-seven (27)']::text[], '[{"key":"a1","display":"twenty-seven (27)","aliases":["27","twenty-seven"]}]'::jsonb, '[["10"],["21"],["26"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution has 27 amendments; 10 is the number in the Bill of Rights, while 21 and 26 are other amendment numbers.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 8, 1, ARRAY['announced our independence (from Great Britain)', 'declared our independence (from Great Britain)', 'said that the United States is free (from Great Britain)']::text[], '[{"key":"independence","display":"announced our independence (from Great Britain)","aliases":["declared our independence (from Great Britain)","said that the United States is free (from Great Britain)","announced our independence","announced our independence from Great Britain","declared our independence","declared our independence from Great Britain","said that the United States is free","said that the United States is free from Great Britain"]}]'::jsonb, '[["Created the federal government"],["Established the first ten amendments"],["Ended all taxes on the colonies"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration announced independence from Britain; it did not create the later federal government, amendments, or tax system.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 9, 2, ARRAY['life', 'liberty', 'pursuit of happiness']::text[], '[{"key":"a1","display":"life","aliases":[]},{"key":"a2","display":"liberty","aliases":[]},{"key":"a3","display":"pursuit of happiness","aliases":[]}]'::jsonb, '[["right to vote","right to bear arms"],["freedom of assembly","freedom of religion"],["right to a jury trial","right to petition Congress"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration names life, liberty, and pursuit of happiness. The proposed pairs substitute later constitutional rights or other civic rights for those stated principles.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 10, 1, ARRAY['You can practice any religion, or not practice a religion.']::text[], '[{"key":"a1","display":"You can practice any religion, or not practice a religion.","aliases":[]}]'::jsonb, '[["You must practice the religion chosen by the government"],["Religious practice is allowed only in private"],["People must belong to a religious group"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Religious freedom protects the choice to practice any religion or none; government compulsion and limits on private practice contradict that freedom.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 11, 1, ARRAY['capitalist economy', 'market economy']::text[], '[{"key":"a1","display":"capitalist economy","aliases":[]},{"key":"a2","display":"market economy","aliases":[]}]'::jsonb, '[["command economy"],["feudal economy"],["barter-only economy"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. economy is capitalist/market based; command, feudal, and barter-only systems describe different economic structures.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 12, 1, ARRAY['Everyone must follow the law.', 'Leaders must obey the law.', 'Government must obey the law.', 'No one is above the law.']::text[], '[{"key":"a1","display":"Everyone must follow the law.","aliases":[]},{"key":"a2","display":"Leaders must obey the law.","aliases":[]},{"key":"a3","display":"Government must obey the law.","aliases":[]},{"key":"a4","display":"No one is above the law.","aliases":[]}]'::jsonb, '[["The President is above the law"],["Only citizens must obey the law"],["Officials may ignore laws they dislike"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Rule of law binds leaders and government to law; the alternatives explicitly exempt officials or citizens from that principle.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 13, 1, ARRAY['Congress', 'legislative', 'President', 'executive', 'the courts', 'judicial']::text[], '[{"key":"legislative","display":"Congress","aliases":["legislative","legislative branch"]},{"key":"executive","display":"the President","aliases":["President","executive","executive branch"]},{"key":"judicial","display":"the courts","aliases":["judicial","judicial branch"]}]'::jsonb, '[["a private corporation"],["a political party"],["a newspaper"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The answers must name a governmental branch or governmental component. A newspaper, private company, or political party is an outside organization, not a branch or part of government.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 14, 1, ARRAY['checks and balances', 'separation of powers']::text[], '[{"key":"a1","display":"checks and balances","aliases":[]},{"key":"a2","display":"separation of powers","aliases":[]}]'::jsonb, '[["unlimited executive authority"],["one branch controls all government powers"],["rule by a hereditary monarch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Checks and balances and separation of powers limit concentration of authority. The proposed systems concentrate power in one person, branch, or inherited office.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 15, 1, ARRAY['the President']::text[], '[{"key":"a1","display":"the President","aliases":["President"]}]'::jsonb, '[["the Speaker of the House"],["the Chief Justice"],["the Secretary of State"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The executive branch is led by the President, not by the legislative Speaker, Chief Justice, or Secretary of State.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 16, 1, ARRAY['Congress', 'Senate and House (of Representatives)', '(U.S. or national) legislature']::text[], '[{"key":"congress","display":"Congress","aliases":["Senate and House (of Representatives)","Senate and House of Representatives","(U.S. or national) legislature","U.S. legislature","national legislature"]}]'::jsonb, '[["the President"],["the Supreme Court"],["the Cabinet"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Federal laws are made by Congress; the executive and judicial branches do not enact federal statutes.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 17, 2, ARRAY['the Senate and House (of Representatives)']::text[], '[{"key":"senate","display":"Senate","aliases":["the Senate"]},{"key":"house","display":"House of Representatives","aliases":["House","the House of Representatives"]}]'::jsonb, '[["President","Cabinet"],["Supreme Court","federal courts"],["governor","state legislature"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Congress consists of the Senate and House of Representatives. The proposed pairs name executive or judicial offices/courts, not the two chambers of Congress.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 18, 1, ARRAY['one hundred (100)']::text[], '[{"key":"a1","display":"one hundred (100)","aliases":["100","one hundred"]}]'::jsonb, '[["50"],["435"],["1,000"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Senate has 100 seats. Fifty is the number of states; 435 is the House voting-member count.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 19, 1, ARRAY['six (6)']::text[], '[{"key":"a1","display":"six (6)","aliases":["6","six","6 year","6 years","six year","six years"]}]'::jsonb, '[["two years"],["four years"],["eight years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A U.S. senator serves a six-year term; two and four years are other elected-office terms.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 20, 1, ARRAY[]::text[], '[]'::jsonb, '[["John R. Curtis"],["Lisa Murkowski"],["Cory Booker"],["Susan Collins"],["Tammy Duckworth"],["Ted Cruz"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The named people hold U.S. Senate seats for other states; none is a senator representing the selected state. Runtime adds and filters current senators from other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.senate.gov/general/resources/pdf/senators_phone_list.pdf', 'https://www.senate.gov/senators/Class_II.htm', 'https://www.senate.gov/senators/Class_III.htm', 'https://www.senate.gov/senators/AppointedSenators.htm']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 21, 1, ARRAY['four hundred thirty-five (435)']::text[], '[{"key":"a1","display":"four hundred thirty-five (435)","aliases":["435","four hundred thirty-five"]}]'::jsonb, '[["100"],["50"],["500"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The House has 435 voting members; 100 is the Senate count and 50 is the number of states.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 22, 1, ARRAY['two (2)']::text[], '[{"key":"a1","display":"two (2)","aliases":["2","two","2 year","2 years","two year","two years"]}]'::jsonb, '[["one year"],["four years"],["six years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A House member serves a two-year term; the other durations do not match the constitutional House term.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 23, 1, ARRAY[]::text[], '[]'::jsonb, '[["Mike Kennedy"],["Sarah McBride"],["Alexandria Ocasio-Cortez"],["Hakeem Jeffries"],["Brian Fitzpatrick"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The named people represent other congressional districts; none represents the selected district. Runtime adds and filters current House members from other districts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://clerk.house.gov/xml/lists/MemberData.xml', 'https://clerk.house.gov/Members/ViewVacancies']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 24, 1, ARRAY['all people of the state']::text[], '[{"key":"a1","display":"all people of the state","aliases":[]}]'::jsonb, '[["the people of one congressional district"],["only the federal government"],["the people of the entire country"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A U.S. senator represents all people of that state, not one district, only the federal government, or the whole nation.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 25, 1, ARRAY['(because of) the state’s population', '(because) they have more people', '(because) some states have more people']::text[], '[{"key":"a1","display":"(because of) the state’s population","aliases":["the state’s population","because of the state’s population"]},{"key":"a2","display":"(because) they have more people","aliases":["they have more people","because they have more people"]},{"key":"a3","display":"(because) some states have more people","aliases":["some states have more people","because some states have more people"]}]'::jsonb, '[["the state’s land area"],["the state’s age"],["the number of counties in the state"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'House seats are apportioned by population; land area, state age, and county count do not determine the number of representatives.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 26, 1, ARRAY['four (4)']::text[], '[{"key":"a1","display":"four (4)","aliases":["4","four","4 year","4 years","four year","four years"]}]'::jsonb, '[["two years"],["six years"],["eight years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President serves a four-year term; two, six, and eight years are different durations.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 27, 1, ARRAY['November']::text[], '[{"key":"a1","display":"November","aliases":[]}]'::jsonb, '[["January"],["May"],["September"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Federal presidential elections are held in November, not January, May, or September.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 28, 1, ARRAY[]::text[], '[]'::jsonb, '[["Joe Biden"],["Barack Obama"],["George W. Bush"],["Bill Clinton"],["George H. W. Bush"],["Ronald Reagan"],["Jimmy Carter"],["Gerald Ford"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named former Presidents no longer hold the current office; the active national answer row supplies the accepted current name and its reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 29, 1, ARRAY[]::text[], '[]'::jsonb, '[["Kamala Harris"],["Mike Pence"],["Tim Kaine"],["Joe Biden"],["Dick Cheney"],["Al Gore"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named people are former Vice Presidents; the active national answer row supplies only the current officeholder and reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 30, 1, ARRAY['the Vice President']::text[], '[{"key":"a1","display":"the Vice President","aliases":["Vice President"]}]'::jsonb, '[["the Speaker of the House"],["the Chief Justice"],["the Secretary of Defense"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Vice President succeeds the President when the President cannot serve; the distractors are not first in the succession rule.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 31, 1, ARRAY['the Speaker of the House']::text[], '[{"key":"a1","display":"the Speaker of the House","aliases":["Speaker of the House"]}]'::jsonb, '[["the Vice President"],["the Chief Justice"],["the Secretary of State"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'When both President and Vice President cannot serve, the Speaker is next in the succession order; the other offices are not next.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 32, 1, ARRAY['the President']::text[], '[{"key":"a1","display":"the President","aliases":["President"]}]'::jsonb, '[["the Secretary of Defense"],["the Speaker of the House"],["the Chairman of the Joint Chiefs of Staff"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President is Commander in Chief; the Secretary of Defense and military chair advise or administer but do not hold that constitutional role.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 33, 1, ARRAY['the President']::text[], '[{"key":"a1","display":"the President","aliases":["President"]}]'::jsonb, '[["the Vice President"],["the Speaker of the House"],["the Chief Justice"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President signs bills into law; the Speaker, Vice President, and Chief Justice do not sign federal bills into law.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 34, 1, ARRAY['the President']::text[], '[{"key":"a1","display":"the President","aliases":["President"]}]'::jsonb, '[["Congress"],["the Vice President"],["the Supreme Court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President vetoes bills; Congress, the Vice President, and Supreme Court do not exercise the presidential veto.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 35, 1, ARRAY['advises the President']::text[], '[{"key":"a1","display":"advises the President","aliases":[]}]'::jsonb, '[["commands the military"],["decides whether laws are constitutional"],["writes federal statutes"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Cabinet advises the President; commanding the military, judicial review, and writing statutes belong to other functions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 36, 2, ARRAY['Secretary of Agriculture', 'Secretary of Commerce', 'Secretary of Defense', 'Secretary of Education', 'Secretary of Energy', 'Secretary of Health and Human Services', 'Secretary of Homeland Security', 'Secretary of Housing and Urban Development', 'Secretary of the Interior', 'Secretary of Labor', 'Secretary of State', 'Secretary of Transportation', 'Secretary of the Treasury', 'Secretary of Veterans Affairs', 'Attorney General', 'Vice President']::text[], '[{"key":"a1","display":"Secretary of Agriculture","aliases":[]},{"key":"a2","display":"Secretary of Commerce","aliases":[]},{"key":"a3","display":"Secretary of Defense","aliases":[]},{"key":"a4","display":"Secretary of Education","aliases":[]},{"key":"a5","display":"Secretary of Energy","aliases":[]},{"key":"a6","display":"Secretary of Health and Human Services","aliases":[]},{"key":"a7","display":"Secretary of Homeland Security","aliases":[]},{"key":"a8","display":"Secretary of Housing and Urban Development","aliases":[]},{"key":"a9","display":"Secretary of the Interior","aliases":[]},{"key":"a10","display":"Secretary of Labor","aliases":[]},{"key":"a11","display":"Secretary of State","aliases":[]},{"key":"a12","display":"Secretary of Transportation","aliases":[]},{"key":"a13","display":"Secretary of the Treasury","aliases":[]},{"key":"a14","display":"Secretary of Veterans Affairs","aliases":[]},{"key":"a15","display":"Attorney General","aliases":[]},{"key":"a16","display":"Vice President","aliases":[]}]'::jsonb, '[["Deputy Secretary of State","White House Press Secretary"],["Assistant Secretary of the Treasury","Deputy Attorney General"],["Deputy Secretary of Defense","Deputy Secretary of Labor"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The accepted titles are Cabinet-level department heads or officers; the listed deputies, press secretary, and staff roles are subordinate support jobs.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 37, 1, ARRAY['reviews laws', 'explains laws', 'resolves disputes (disagreements)', 'decides if a law goes against the Constitution']::text[], '[{"key":"a1","display":"reviews laws","aliases":[]},{"key":"a2","display":"explains laws","aliases":[]},{"key":"a3","display":"resolves disputes (disagreements)","aliases":["resolves disputes","resolves disagreements"]},{"key":"a4","display":"decides if a law goes against the Constitution","aliases":[]}]'::jsonb, '[["writes laws"],["commands the military"],["vetoes bills"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The judicial branch reviews and interprets law; it does not write statutes, command the military, or veto bills.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 38, 1, ARRAY['the Supreme Court']::text[], '[{"key":"a1","display":"the Supreme Court","aliases":["Supreme Court"]}]'::jsonb, '[["a federal court of appeals"],["a state supreme court"],["a federal district court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. Supreme Court is the nation’s highest court; circuit, state, and district courts are lower courts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 39, 1, ARRAY['nine (9)']::text[], '[{"key":"a1","display":"nine (9)","aliases":["9","nine"]}]'::jsonb, '[["five"],["seven"],["eleven"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Nine justices sit on the Supreme Court; five, seven, and eleven are not its membership count.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 40, 1, ARRAY[]::text[], '[]'::jsonb, '[["William Rehnquist"],["Warren Burger"],["Earl Warren"],["Harlan Fiske Stone"],["Charles Evans Hughes"],["John Marshall"],["Roger Taney"],["Salmon P. Chase"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named people are former Chief Justices or other justices; the active national answer row supplies only the current Chief Justice and reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 41, 1, ARRAY['to print money', 'to declare war', 'to create an army', 'to make treaties']::text[], '[{"key":"a1","display":"to print money","aliases":[]},{"key":"a2","display":"to declare war","aliases":[]},{"key":"a3","display":"to create an army","aliases":[]},{"key":"a4","display":"to make treaties","aliases":[]}]'::jsonb, '[["issue a state driver license"],["approve a city zoning permit"],["issue a local building permit"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A state driver license, city zoning approval, and local building permit are government powers exercised by state/local authorities, not federal powers.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 42, 1, ARRAY['provide schooling and education', 'provide protection (police)', 'provide safety (fire departments)', 'give a driver’s license', 'approve zoning and land use']::text[], '[{"key":"a1","display":"provide schooling and education","aliases":[]},{"key":"a2","display":"provide protection (police)","aliases":["provide protection","provide protection police"]},{"key":"a3","display":"provide safety (fire departments)","aliases":["provide safety","provide safety fire departments"]},{"key":"a4","display":"give a driver’s license","aliases":[]},{"key":"a5","display":"approve zoning and land use","aliases":[]}]'::jsonb, '[["declare war"],["make treaties"],["print paper money"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Declaring war, making treaties, and printing money are federal powers; they are not powers reserved to the states in the USCIS answer list.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 43, 1, ARRAY[]::text[], '[]'::jsonb, '[["Gavin Newsom"],["Greg Abbott"],["Jared Polis"],["Spencer Cox"],["J.B. Pritzker"],["Sarah Huckabee Sanders"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The named people govern other states; none is governor of the selected state. Runtime adds and filters current governors from other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.nga.org/governors/']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 44, 1, ARRAY[]::text[], '[]'::jsonb, '[["Denver"],["Sacramento"],["Phoenix"],["Austin"],["Albany"],["Boston"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"official_variants_only","distractors":"other_geographies"}'::jsonb, 'The named cities are capitals of other states, not the selected state’s capital. Runtime adds and filters capital values for the other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.lrl.mn.gov/docs/2013/other/130551.pdf', 'https://www.census.gov/content/dam/Census/library/publications/2015/demo/p23-213.pdf', 'https://www.mcog.guam.gov/villages-list?keyword=capital', 'https://home.treasury.gov/system/files/136/San-Juan-Municipio-Puerto-Rico_2024-Recovery-Plan_SLT-2215.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 45, 2, ARRAY['Democratic and Republican']::text[], '[{"key":"democratic","display":"Democratic Party","aliases":["Democratic","Democratic Party"]},{"key":"republican","display":"Republican Party","aliases":["Republican","Republican Party"]}]'::jsonb, '[["Green Party","Libertarian Party"],["Libertarian Party","Constitution Party"],["Constitution Party","Working Families Party"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Democratic and Republican parties are the two major U.S. parties; the Green, Libertarian, Constitution, and Working Families parties are smaller third parties.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 46, 1, ARRAY[]::text[], '[]'::jsonb, '[["Democratic Party"],["Green Party"],["Libertarian Party"],["Constitution Party"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"political_party","distractors":"curated"}'::jsonb, 'The named former Presidents no longer hold the current office; the active national answer row supplies the accepted current name and its reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 47, 1, ARRAY[]::text[], '[]'::jsonb, '[["Nancy Pelosi"],["Paul Ryan"],["John Boehner"],["Kevin McCarthy"],["Newt Gingrich"],["Dennis Hastert"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named people are former Speakers; the active national answer row supplies only the current Speaker and reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 48, 1, ARRAY['Citizens eighteen (18) and older (can vote).', 'You don’t have to pay (a poll tax) to vote.', 'Any citizen can vote. (Women and men can vote.)', 'A male citizen of any race (can vote).']::text[], '[{"key":"a1","display":"Citizens eighteen (18) and older (can vote).","aliases":["Citizens 18 and older.","Citizens eighteen and older.","Citizens 18 and older can vote.","Citizens eighteen and older can vote."]},{"key":"a2","display":"You don’t have to pay (a poll tax) to vote.","aliases":["You don’t have to pay to vote.","You don’t have to pay a poll tax to vote."]},{"key":"a3","display":"Any citizen can vote. (Women and men can vote.)","aliases":["Any citizen can vote.","Any citizen can vote. Women and men can vote."]},{"key":"a4","display":"A male citizen of any race (can vote).","aliases":["A male citizen of any race.","A male citizen of any race can vote.","male citizen of any race (can vote)."]}]'::jsonb, '[["Only landowners may vote"],["Only men may vote"],["Citizens must pay a poll tax to vote"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The voting amendments prohibit voting restrictions based on race, sex, age at least 18, or poll taxes. The proposed restrictions contradict those protections.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 49, 1, ARRAY['serve on a jury', 'vote in a federal election']::text[], '[{"key":"a1","display":"serve on a jury","aliases":[]},{"key":"a2","display":"vote in a federal election","aliases":[]}]'::jsonb, '[["pay federal taxes"],["attend public school"],["serve in the U.S. military"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Paying taxes, attending school, and military service are not limited to U.S. citizens; jury service and voting in federal elections are citizen-only responsibilities in this answer bank.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 50, 1, ARRAY['vote in a federal election', 'run for federal office']::text[], '[{"key":"a1","display":"vote in a federal election","aliases":[]},{"key":"a2","display":"run for federal office","aliases":[]}]'::jsonb, '[["freedom of speech"],["freedom of religion"],["the right to bear arms"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Speech, religion, and bearing arms are rights held by people living in the United States, not rights reserved only to citizens.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 51, 2, ARRAY['freedom of expression', 'freedom of speech', 'freedom of assembly', 'freedom to petition the government', 'freedom of religion', 'the right to bear arms']::text[], '[{"key":"expression","display":"freedom of expression","aliases":["freedom of speech","speech"]},{"key":"assembly","display":"freedom of assembly","aliases":["assembly"]},{"key":"petition","display":"freedom to petition the government","aliases":["petition the government"]},{"key":"religion","display":"freedom of religion","aliases":["religion"]},{"key":"arms","display":"right to bear arms","aliases":["bear arms"]}]'::jsonb, '[["a right to require an official national religion","a right to silence peaceful criticism"],["a right to prevent peaceful assembly","a right to control private beliefs"],["a right to ban petitions to government","a right to censor all newspapers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The named freedoms are protections for people living in the United States. The proposed powers to censor, impose religion, or suppress peaceful activity are not protected rights.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 52, 1, ARRAY['the United States', 'the flag']::text[], '[{"key":"a1","display":"the United States","aliases":["United States"]},{"key":"a2","display":"the flag","aliases":["flag"]}]'::jsonb, '[["the Constitution"],["the President"],["Congress"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Pledge is loyalty to the United States or its flag, not to an officeholder or Congress.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 53, 1, ARRAY['give up loyalty to other countries', 'defend the Constitution and laws of the United States', 'obey the laws of the United States', 'serve in the U.S. military (if needed)', 'serve (do important work for) the nation (if needed)', 'be loyal to the United States']::text[], '[{"key":"a1","display":"give up loyalty to other countries","aliases":[]},{"key":"a2","display":"defend the Constitution and laws of the United States","aliases":[]},{"key":"a3","display":"obey the laws of the United States","aliases":[]},{"key":"a4","display":"serve in the U.S. military (if needed)","aliases":["serve in the U.S. military","serve in the U.S. military if needed"]},{"key":"a5","display":"serve (do important work for) the nation (if needed)","aliases":["serve the nation","serve the nation if needed","serve do important work for the nation","serve do important work for the nation if needed"]},{"key":"a6","display":"be loyal to the United States","aliases":[]}]'::jsonb, '[["promise to become a federal employee"],["promise to vote in every election"],["promise to serve on a jury every year"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Oath includes loyalty, obeying and defending U.S. law and service if needed; employment, annual jury duty, and mandatory voting are not its promises.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 54, 1, ARRAY['eighteen (18) and older']::text[], '[{"key":"a1","display":"eighteen (18) and older","aliases":["18","eighteen","18 and older","eighteen and older"]}]'::jsonb, '[["sixteen"],["twenty-one"],["twenty-five"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Citizens may vote for President at 18; 16 is too young, while 21 and 25 are not the voting age.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 55, 2, ARRAY['vote', 'join a political party', 'help with a campaign', 'join a civic group', 'join a community group', 'give an elected official your opinion on an issue', 'call Senators and Representatives', 'publicly support or oppose an issue or policy', 'run for office', 'write to a newspaper']::text[], '[{"key":"a1","display":"vote","aliases":[]},{"key":"a2","display":"join a political party","aliases":[]},{"key":"a3","display":"help with a campaign","aliases":[]},{"key":"a4","display":"join a civic group","aliases":[]},{"key":"a5","display":"join a community group","aliases":[]},{"key":"a6","display":"give an elected official your opinion on an issue","aliases":[]},{"key":"a7","display":"call Senators and Representatives","aliases":[]},{"key":"a8","display":"publicly support or oppose an issue or policy","aliases":[]},{"key":"a9","display":"run for office","aliases":[]},{"key":"a10","display":"write to a newspaper","aliases":[]}]'::jsonb, '[["avoid public affairs","refuse to contact officials"],["ignore elections","prevent others from voting"],["refuse all community activity","avoid public meetings"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Democratic participation consists of constructive civic actions. Withdrawing from public affairs or preventing voting does not participate in democracy.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 56, 1, ARRAY['April 15']::text[], '[{"key":"a1","display":"April 15","aliases":["April 15th","15 April"]}]'::jsonb, '[["May 15"],["September 30"],["December 31"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'April 15 is the standard federal individual return deadline; May 15, September 30, and December 31 are not the standard filing date.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.irs.gov/individual-tax-filing']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 57, 1, ARRAY['at age eighteen (18)', 'between eighteen (18) and twenty-six (26)']::text[], '[{"key":"a1","display":"at age eighteen (18)","aliases":["at age 18","at age eighteen","18","eighteen"]},{"key":"a2","display":"between eighteen (18) and twenty-six (26)","aliases":["between 18 and 26","between eighteen and 26","between 18 and twenty-six","between eighteen and twenty-six"]}]'::jsonb, '[["at age sixteen"],["at age thirty"],["at age thirty-five"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Selective Service registration applies at 18 or between 18 and 26; 16, 30, and 35 fall outside that stated range.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 58, 1, ARRAY['freedom', 'political liberty', 'religious freedom', 'economic opportunity', 'practice their religion', 'escape persecution']::text[], '[{"key":"a1","display":"freedom","aliases":[]},{"key":"a2","display":"political liberty","aliases":[]},{"key":"a3","display":"religious freedom","aliases":[]},{"key":"a4","display":"economic opportunity","aliases":[]},{"key":"a5","display":"practice their religion","aliases":[]},{"key":"a6","display":"escape persecution","aliases":[]}]'::jsonb, '[["to join the 1849 California Gold Rush"],["to serve in the U.S. Peace Corps"],["to take part in the Apollo program"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The California Gold Rush, Peace Corps, and Apollo program arose long after colonial settlement; none could have motivated colonists to come to America.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 59, 1, ARRAY['American Indians', 'Native Americans']::text[], '[{"key":"a1","display":"American Indians","aliases":[]},{"key":"a2","display":"Native Americans","aliases":[]}]'::jsonb, '[["Spanish settlers"],["British colonists"],["French explorers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Before European arrival, the people in America were Indigenous peoples; Spanish settlers, British colonists, and French explorers were European arrivals, not pre-contact inhabitants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 60, 1, ARRAY['Africans', 'people from Africa']::text[], '[{"key":"a1","display":"Africans","aliases":[]},{"key":"a2","display":"people from Africa","aliases":[]}]'::jsonb, '[["British merchants"],["European colonists"],["people from Australia"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The answer refers to Africans forcibly transported and sold into slavery in America; merchants and European colonists were not the people described by that question.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 61, 1, ARRAY['because of high taxes (taxation without representation)', 'because the British army stayed in their houses (boarding, quartering)', 'because they didn’t have self-government']::text[], '[{"key":"a1","display":"because of high taxes (taxation without representation)","aliases":["because of high taxes","high taxes","taxation without representation"]},{"key":"a2","display":"because the British army stayed in their houses (boarding, quartering)","aliases":["because the British army stayed in their houses","quartering","boarding","British soldiers stayed in their houses"]},{"key":"a3","display":"because they didn’t have self-government","aliases":[]}]'::jsonb, '[["because Britain granted the colonies full self-government"],["because Britain ended all colonial taxes"],["because the colonists wanted a monarch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Colonists fought over British taxation, quartering, and lack of self-government; the distractors reverse those grievances or claim support for monarchy.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 62, 1, ARRAY['(Thomas) Jefferson']::text[], '[{"key":"a1","display":"(Thomas) Jefferson","aliases":["Jefferson","Thomas Jefferson"]}]'::jsonb, '[["George Washington"],["Alexander Hamilton"],["James Madison"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Thomas Jefferson wrote the Declaration; Washington, Hamilton, and Madison were not its author.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf', 'https://www.archives.gov/founding-docs/declaration-history']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 63, 1, ARRAY['July 4, 1776']::text[], '[{"key":"a1","display":"July 4, 1776","aliases":["July 4th, 1776","4 July 1776","July Fourth, 1776"]}]'::jsonb, '[["July 2, 1776"],["July 4, 1787"],["June 4, 1776"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration was adopted on July 4, 1776. The distractors change the day or year, so none states the full adoption date.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 64, 3, ARRAY['New Hampshire', 'Massachusetts', 'Rhode Island', 'Connecticut', 'New York', 'New Jersey', 'Pennsylvania', 'Delaware', 'Maryland', 'Virginia', 'North Carolina', 'South Carolina', 'Georgia']::text[], '[{"key":"a1","display":"New Hampshire","aliases":[]},{"key":"a2","display":"Massachusetts","aliases":[]},{"key":"a3","display":"Rhode Island","aliases":[]},{"key":"a4","display":"Connecticut","aliases":[]},{"key":"a5","display":"New York","aliases":[]},{"key":"a6","display":"New Jersey","aliases":[]},{"key":"a7","display":"Pennsylvania","aliases":[]},{"key":"a8","display":"Delaware","aliases":[]},{"key":"a9","display":"Maryland","aliases":[]},{"key":"a10","display":"Virginia","aliases":[]},{"key":"a11","display":"North Carolina","aliases":[]},{"key":"a12","display":"South Carolina","aliases":[]},{"key":"a13","display":"Georgia","aliases":[]}]'::jsonb, '[["Ohio","Kentucky","Tennessee"],["Maine","Florida","California"],["Texas","Hawaii","Oregon"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The listed original states were among the thirteen colonies that formed the original states. Ohio, Kentucky, Tennessee, Maine, Florida, California, Texas, and Hawaii entered the Union later.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 65, 1, ARRAY['The Constitution was written.', 'The Founding Fathers wrote the Constitution.']::text[], '[{"key":"a1","display":"The Constitution was written.","aliases":["Constitution was written."]},{"key":"a2","display":"The Founding Fathers wrote the Constitution.","aliases":["Founding Fathers wrote the Constitution."]}]'::jsonb, '[["The Declaration of Independence was written"],["The Bill of Rights was adopted"],["The Articles of Confederation were signed"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitutional Convention produced the Constitution, not the Declaration, Bill of Rights, or Articles of Confederation.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 66, 1, ARRAY['1787']::text[], '[{"key":"a1","display":"1787","aliases":[]}]'::jsonb, '[["1776"],["1781"],["1789"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution was written in 1787; 1776 marks independence and 1781/1789 refer to different milestones.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 67, 1, ARRAY['(James) Madison', '(Alexander) Hamilton', '(John) Jay', 'Publius']::text[], '[{"key":"a1","display":"(James) Madison","aliases":["Madison","James Madison"]},{"key":"a2","display":"(Alexander) Hamilton","aliases":["Hamilton","Alexander Hamilton"]},{"key":"a3","display":"(John) Jay","aliases":["Jay","John Jay"]},{"key":"a4","display":"Publius","aliases":[]}]'::jsonb, '[["Thomas Jefferson"],["John Adams"],["Patrick Henry"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Madison, Hamilton, and Jay wrote the Federalist Papers; Jefferson, Adams, and Henry were not the listed authors.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 68, 1, ARRAY['U.S. diplomat', 'oldest member of the Constitutional Convention', 'first Postmaster General of the United States', 'writer of “Poor Richard’s Almanac”', 'started the first free libraries']::text[], '[{"key":"a1","display":"U.S. diplomat","aliases":[]},{"key":"a2","display":"oldest member of the Constitutional Convention","aliases":[]},{"key":"a3","display":"first Postmaster General of the United States","aliases":[]},{"key":"a4","display":"writer of “Poor Richard’s Almanac”","aliases":[]},{"key":"a5","display":"started the first free libraries","aliases":[]}]'::jsonb, '[["served as President"],["commanded the Continental Army"],["served as Chief Justice"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The stated achievements are Franklin’s public service, diplomacy, writing, and library work; he was neither President nor Army commander nor Chief Justice.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 69, 1, ARRAY['(George) Washington']::text[], '[{"key":"a1","display":"(George) Washington","aliases":["Washington","George Washington"]}]'::jsonb, '[["Thomas Jefferson"],["John Adams"],["Benjamin Franklin"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'George Washington is called the Father of Our Country; Jefferson, Adams, and Franklin do not hold that title.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 70, 1, ARRAY['(George) Washington']::text[], '[{"key":"a1","display":"(George) Washington","aliases":["Washington","George Washington"]}]'::jsonb, '[["John Adams"],["Thomas Jefferson"],["James Madison"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'George Washington was the first President; Adams, Jefferson, and Madison served later.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 71, 1, ARRAY['the Louisiana Territory', 'Louisiana']::text[], '[{"key":"a1","display":"the Louisiana Territory","aliases":["Louisiana Territory"]},{"key":"a2","display":"Louisiana","aliases":[]}]'::jsonb, '[["Florida Territory"],["Oregon Country"],["Alaska"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The 1803 purchase from France was Louisiana; Florida, Oregon Country, and Alaska were acquired by other means or at other times.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 72, 1, ARRAY['War of 1812', 'Mexican-American War', 'Civil War', 'Spanish-American War']::text[], '[{"key":"a1","display":"War of 1812","aliases":[]},{"key":"a2","display":"Mexican-American War","aliases":[]},{"key":"a3","display":"Civil War","aliases":[]},{"key":"a4","display":"Spanish-American War","aliases":[]}]'::jsonb, '[["World War I"],["World War II"],["Korean War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The requested wars occurred in the 1800s; World War I, World War II, and Korea occurred in the 1900s.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 73, 1, ARRAY['the Civil War', 'the War between the States']::text[], '[{"key":"civil-war","display":"the Civil War","aliases":["the War between the States","Civil War","War between the States"]}]'::jsonb, '[["War of 1812"],["Mexican-American War"],["Spanish-American War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Civil War was the North–South war; the War of 1812, Mexican-American War, and Spanish-American War were different conflicts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 74, 1, ARRAY['slavery', 'economic reasons', 'states’ rights']::text[], '[{"key":"a1","display":"slavery","aliases":[]},{"key":"a2","display":"economic reasons","aliases":[]},{"key":"a3","display":"states’ rights","aliases":[]}]'::jsonb, '[["World War I"],["the Great Depression"],["the Cold War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'World War I, the Great Depression, and the Cold War all occurred after the Civil War began, so they could not have caused it.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 75, 1, ARRAY['freed the slaves (Emancipation Proclamation)', 'saved (or preserved) the Union', 'led the United States during the Civil War']::text[], '[{"key":"a1","display":"freed the slaves (Emancipation Proclamation)","aliases":["freed the slaves","Emancipation Proclamation"]},{"key":"a2","display":"saved (or preserved) the Union","aliases":["saved the Union","preserved the Union","saved or preserved the Union"]},{"key":"a3","display":"led the United States during the Civil War","aliases":[]}]'::jsonb, '[["wrote the Declaration of Independence"],["bought the Louisiana Territory"],["commanded the Continental Army during the Revolution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Lincoln freed enslaved people, preserved the Union, and led during the Civil War; he did not write the Declaration or make the Louisiana Purchase.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 76, 1, ARRAY['freed the slaves', 'freed slaves in the Confederacy', 'freed slaves in the Confederate states', 'freed slaves in most Southern states']::text[], '[{"key":"a1","display":"freed the slaves","aliases":[]},{"key":"a2","display":"freed slaves in the Confederacy","aliases":[]},{"key":"a3","display":"freed slaves in the Confederate states","aliases":[]},{"key":"a4","display":"freed slaves in most Southern states","aliases":[]}]'::jsonb, '[["freed enslaved people in every country"],["ended slavery in the states loyal to the Union"],["granted women the right to vote"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Emancipation Proclamation applied to enslaved people in rebelling Confederate areas; it did not abolish slavery worldwide or grant women suffrage.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 77, 1, ARRAY['fought for women’s rights', 'fought for civil rights']::text[], '[{"key":"a1","display":"fought for women’s rights","aliases":[]},{"key":"a2","display":"fought for civil rights","aliases":[]}]'::jsonb, '[["served as President"],["commanded the Continental Army"],["wrote the Constitution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Susan B. Anthony advocated women’s and civil rights; she was not President, Army commander, or author of the Constitution.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 78, 1, ARRAY['World War I', 'World War II', 'Korean War', 'Vietnam War', '(Persian) Gulf War']::text[], '[{"key":"a1","display":"World War I","aliases":["WWI","World War One","First World War"]},{"key":"a2","display":"World War II","aliases":["WWII","World War Two","Second World War"]},{"key":"a3","display":"Korean War","aliases":[]},{"key":"a4","display":"Vietnam War","aliases":[]},{"key":"a5","display":"(Persian) Gulf War","aliases":["Gulf War","Persian Gulf War"]}]'::jsonb, '[["the American Revolution"],["the Civil War"],["the War of 1812"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The question asks for a 1900s war; the American Revolution, Civil War, and War of 1812 occurred earlier.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 79, 1, ARRAY['(Woodrow) Wilson']::text[], '[{"key":"a1","display":"(Woodrow) Wilson","aliases":["Wilson","Woodrow Wilson"]}]'::jsonb, '[["William Howard Taft"],["Franklin Roosevelt"],["Warren G. Harding"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Woodrow Wilson was President during World War I; Taft, Franklin Roosevelt, and Harding served at other times.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 80, 1, ARRAY['(Franklin) Roosevelt']::text[], '[{"key":"a1","display":"(Franklin) Roosevelt","aliases":["Roosevelt","Franklin Roosevelt"]}]'::jsonb, '[["Herbert Hoover"],["Harry Truman"],["Calvin Coolidge"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Franklin Roosevelt was President during the Depression and World War II; Hoover, Truman, and Coolidge do not match both periods.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 81, 3, ARRAY['Japan, Germany, and Italy']::text[], '[{"key":"japan","display":"Japan","aliases":[]},{"key":"germany","display":"Germany","aliases":[]},{"key":"italy","display":"Italy","aliases":[]}]'::jsonb, '[["Britain","France","Soviet Union"],["Soviet Union","China","Australia"],["France","Canada","New Zealand"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Britain, France, the Soviet Union, China, Australia, and Canada fought alongside the United States as Allied powers, not against it.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 82, 1, ARRAY['World War II']::text[], '[{"key":"a1","display":"World War II","aliases":["WWII","World War Two","Second World War"]}]'::jsonb, '[["World War I"],["the Korean War"],["the Spanish-American War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Eisenhower served as a general in World War II; he was not in World War I, Korea, or the Spanish-American War.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 83, 1, ARRAY['Communism']::text[], '[{"key":"a1","display":"Communism","aliases":[]}]'::jsonb, '[["the spread of feudalism"],["piracy on the Atlantic"],["the return of colonial rule"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. Cold War concern was communism; feudalism, Atlantic piracy, and colonial restoration were not the conflict’s central concern.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 84, 1, ARRAY['civil rights (movement)']::text[], '[{"key":"a1","display":"civil rights (movement)","aliases":["civil rights","civil rights movement"]}]'::jsonb, '[["the temperance movement"],["the conservation movement"],["the antitrust movement"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Temperance, conservation, and antitrust movements pursued different reforms; they were not the movement whose stated goal was ending racial discrimination.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 85, 1, ARRAY['fought for civil rights', 'worked for equality for all Americans']::text[], '[{"key":"a1","display":"fought for civil rights","aliases":[]},{"key":"a2","display":"worked for equality for all Americans","aliases":[]}]'::jsonb, '[["served as a U.S. President"],["commanded the Continental Army"],["wrote the Declaration of Independence"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Martin Luther King Jr. fought for civil rights and equality; he was not President, a Revolutionary general, or Declaration author.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 86, 1, ARRAY['Terrorists attacked the United States.']::text[], '[{"key":"a1","display":"Terrorists attacked the United States.","aliases":[]}]'::jsonb, '[["the Moon landing"],["the attack on Pearl Harbor"],["the end of World War II"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'On September 11, 2001, terrorists attacked the United States; the distractors describe unrelated events from other dates.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 87, 1, ARRAY['Cherokee', 'Navajo', 'Sioux', 'Chippewa', 'Choctaw', 'Pueblo', 'Apache', 'Iroquois', 'Creek', 'Blackfeet', 'Seminole', 'Cheyenne', 'Arawak', 'Shawnee', 'Mohegan', 'Huron', 'Oneida', 'Lakota', 'Crow', 'Teton', 'Hopi', 'Inuit']::text[], '[{"key":"a1","display":"Cherokee","aliases":[]},{"key":"a2","display":"Navajo","aliases":[]},{"key":"a3","display":"Sioux","aliases":[]},{"key":"a4","display":"Chippewa","aliases":[]},{"key":"a5","display":"Choctaw","aliases":[]},{"key":"a6","display":"Pueblo","aliases":[]},{"key":"a7","display":"Apache","aliases":[]},{"key":"a8","display":"Iroquois","aliases":[]},{"key":"a9","display":"Creek","aliases":[]},{"key":"a10","display":"Blackfeet","aliases":[]},{"key":"a11","display":"Seminole","aliases":[]},{"key":"a12","display":"Cheyenne","aliases":[]},{"key":"a13","display":"Arawak","aliases":[]},{"key":"a14","display":"Shawnee","aliases":[]},{"key":"a15","display":"Mohegan","aliases":[]},{"key":"a16","display":"Huron","aliases":[]},{"key":"a17","display":"Oneida","aliases":[]},{"key":"a18","display":"Lakota","aliases":[]},{"key":"a19","display":"Crow","aliases":[]},{"key":"a20","display":"Teton","aliases":[]},{"key":"a21","display":"Hopi","aliases":[]},{"key":"a22","display":"Inuit","aliases":[]}]'::jsonb, '[["Amish"],["Cajun"],["Pennsylvania Dutch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Amish, Cajun, and Pennsylvania Dutch communities are not American Indian tribes; the question asks for a tribal nation, not a U.S. cultural or religious community.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 88, 1, ARRAY['Missouri (River)', 'Mississippi (River)']::text[], '[{"key":"a1","display":"Missouri (River)","aliases":["Missouri","Missouri River"]},{"key":"a2","display":"Mississippi (River)","aliases":["Mississippi","Mississippi River"]}]'::jsonb, '[["Colorado River"],["Ohio River"],["Rio Grande"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Missouri and Mississippi are the two longest U.S. rivers; the Colorado, Ohio, and Rio Grande are shorter.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 89, 1, ARRAY['Pacific (Ocean)']::text[], '[{"key":"a1","display":"Pacific (Ocean)","aliases":["Pacific","Pacific Ocean"]}]'::jsonb, '[["Atlantic Ocean"],["Indian Ocean"],["Arctic Ocean"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Pacific borders the West Coast; the Atlantic, Indian, and Arctic Oceans do not.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 90, 1, ARRAY['Atlantic (Ocean)']::text[], '[{"key":"a1","display":"Atlantic (Ocean)","aliases":["Atlantic","Atlantic Ocean"]}]'::jsonb, '[["Pacific Ocean"],["Indian Ocean"],["Arctic Ocean"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Atlantic borders the East Coast; the Pacific, Indian, and Arctic Oceans do not.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 91, 1, ARRAY['Puerto Rico', 'U.S. Virgin Islands', 'American Samoa', 'Northern Mariana Islands', 'Guam']::text[], '[{"key":"a1","display":"Puerto Rico","aliases":[]},{"key":"a2","display":"U.S. Virgin Islands","aliases":[]},{"key":"a3","display":"American Samoa","aliases":[]},{"key":"a4","display":"Northern Mariana Islands","aliases":[]},{"key":"a5","display":"Guam","aliases":[]}]'::jsonb, '[["Hawaii"],["Ontario"],["California"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Hawaii and California are states and Ontario is Canadian; none is a U.S. territory.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 92, 1, ARRAY['Maine', 'New Hampshire', 'Vermont', 'New York', 'Pennsylvania', 'Ohio', 'Michigan', 'Minnesota', 'North Dakota', 'Montana', 'Idaho', 'Washington', 'Alaska']::text[], '[{"key":"a1","display":"Maine","aliases":[]},{"key":"a2","display":"New Hampshire","aliases":[]},{"key":"a3","display":"Vermont","aliases":[]},{"key":"a4","display":"New York","aliases":[]},{"key":"a5","display":"Pennsylvania","aliases":[]},{"key":"a6","display":"Ohio","aliases":[]},{"key":"a7","display":"Michigan","aliases":[]},{"key":"a8","display":"Minnesota","aliases":[]},{"key":"a9","display":"North Dakota","aliases":[]},{"key":"a10","display":"Montana","aliases":[]},{"key":"a11","display":"Idaho","aliases":[]},{"key":"a12","display":"Washington","aliases":[]},{"key":"a13","display":"Alaska","aliases":[]}]'::jsonb, '[["Florida"],["Texas"],["Hawaii"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Florida, Texas, and Hawaii do not border Canada; the U.S.–Canada border states are farther north.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 93, 1, ARRAY['California', 'Arizona', 'New Mexico', 'Texas']::text[], '[{"key":"a1","display":"California","aliases":[]},{"key":"a2","display":"Arizona","aliases":[]},{"key":"a3","display":"New Mexico","aliases":[]},{"key":"a4","display":"Texas","aliases":[]}]'::jsonb, '[["Oklahoma"],["Colorado"],["Nevada"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Oklahoma, Colorado, and Nevada do not border Mexico; the four border states are California, Arizona, New Mexico, and Texas.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 94, 1, ARRAY['Washington, D.C.']::text[], '[{"key":"a1","display":"Washington, D.C.","aliases":["Washington DC","Washington D.C.","Washington D C"]}]'::jsonb, '[["Philadelphia"],["New York City"],["Boston"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Washington, D.C. is the national capital; Philadelphia, New York, and Boston were not selected as the capital.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 95, 1, ARRAY['New York (Harbor)', 'Liberty Island', 'New Jersey', 'near New York City', 'on the Hudson (River)']::text[], '[{"key":"a1","display":"New York (Harbor)","aliases":["New York","New York Harbor"]},{"key":"a2","display":"Liberty Island","aliases":[]},{"key":"a3","display":"New Jersey","aliases":[]},{"key":"a4","display":"near New York City","aliases":[]},{"key":"a5","display":"on the Hudson (River)","aliases":["on the Hudson","on the Hudson River"]}]'::jsonb, '[["Boston Harbor, Massachusetts"],["Potomac River, Virginia"],["San Francisco Bay, California"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Statue of Liberty stands in New York Harbor on Liberty Island; the listed West Coast, Boston, and Potomac sites are elsewhere.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 96, 1, ARRAY['because there were 13 original colonies', 'because the stripes represent the original colonies']::text[], '[{"key":"a1","display":"because there were 13 original colonies","aliases":[]},{"key":"a2","display":"because the stripes represent the original colonies","aliases":[]}]'::jsonb, '[["the 50 states"],["the first 13 amendments"],["the 13 Presidents"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The thirteen stripes represent the original colonies, not fifty states, amendments, or Presidents.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 97, 1, ARRAY['because there is one star for each state', 'because each star represents a state', 'because there are 50 states']::text[], '[{"key":"a1","display":"because there is one star for each state","aliases":[]},{"key":"a2","display":"because each star represents a state","aliases":[]},{"key":"a3","display":"because there are 50 states","aliases":[]}]'::jsonb, '[["the 13 original colonies"],["one star for each U.S. territory"],["the 50 original states"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The fifty stars correspond to the fifty states, not colonies, territories, or original states.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 98, 1, ARRAY['The Star-Spangled Banner']::text[], '[{"key":"a1","display":"The Star-Spangled Banner","aliases":["Star-Spangled Banner"]}]'::jsonb, '[["America the Beautiful"],["My Country, ’Tis of Thee"],["God Bless America"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The national anthem is “The Star-Spangled Banner”; the distractors are other patriotic songs or symbols.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 99, 1, ARRAY['July 4']::text[], '[{"key":"a1","display":"July 4","aliases":["July 4th","4 July","Fourth of July"]}]'::jsonb, '[["November 11"],["January 1"],["May 1"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Independence Day is celebrated July 4, not November 11, January 1, or May 1.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2008', 100, 2, ARRAY['New Year’s Day', 'Martin Luther King, Jr. Day', 'Presidents’ Day', 'Memorial Day', 'Juneteenth', 'Independence Day', 'Labor Day', 'Columbus Day', 'Veterans Day', 'Thanksgiving', 'Christmas']::text[], '[{"key":"a1","display":"New Year’s Day","aliases":[]},{"key":"a2","display":"Martin Luther King, Jr. Day","aliases":["MLK Day","Martin Luther King Day"]},{"key":"a3","display":"Presidents’ Day","aliases":["Presidents Day","Washington’s Birthday","Washington''s Birthday"]},{"key":"a4","display":"Memorial Day","aliases":[]},{"key":"a5","display":"Juneteenth","aliases":[]},{"key":"a6","display":"Independence Day","aliases":[]},{"key":"a7","display":"Labor Day","aliases":[]},{"key":"a8","display":"Columbus Day","aliases":[]},{"key":"a9","display":"Veterans Day","aliases":[]},{"key":"a10","display":"Thanksgiving","aliases":["Thanksgiving Day"]},{"key":"a11","display":"Christmas","aliases":["Christmas Day"]}]'::jsonb, '[["Texas Independence Day","Patriots’ Day"],["César Chávez Day","Confederate Memorial Day"],["Alaska Day","Patriots’ Day"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The accepted options are national federal holidays; Texas Independence Day, Patriots’ Day, César Chávez Day, Confederate Memorial Day, and Alaska Day are regional observances.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/OoC_100_Questions_2008_Civics_Test_V1.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 1, 1, ARRAY['Republic', 'Constitution-based federal republic', 'Representative democracy']::text[], '[{"key":"a1","display":"Republic","aliases":[]},{"key":"a2","display":"Constitution-based federal republic","aliases":[]},{"key":"a3","display":"Representative democracy","aliases":[]}]'::jsonb, '[["absolute monarchy"],["military dictatorship"],["hereditary theocracy"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The United States is a constitutional federal republic and representative democracy; monarchy and dictatorship place authority in a ruler or unelected regime.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 2, 1, ARRAY['(U.S.) Constitution']::text[], '[{"key":"a1","display":"(U.S.) Constitution","aliases":["Constitution","U.S. Constitution"]}]'::jsonb, '[["Declaration of Independence"],["Articles of Confederation"],["Federalist Papers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. Constitution is the supreme law. The other named founding documents are important but do not hold that legal status.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 3, 1, ARRAY['Forms the government', 'Defines powers of government', 'Defines the parts of government', 'Protects the rights of the people']::text[], '[{"key":"a1","display":"Forms the government","aliases":[]},{"key":"a2","display":"Defines powers of government","aliases":[]},{"key":"a3","display":"Defines the parts of government","aliases":[]},{"key":"a4","display":"Protects the rights of the people","aliases":[]}]'::jsonb, '[["It sets the federal tax deadline"],["It elects state governors"],["It names the national anthem"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution forms government, defines its powers and parts, and protects rights; setting the tax date, electing governors, and naming the anthem are not its functions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 4, 1, ARRAY['Self-government', 'Popular sovereignty', 'Consent of the governed', 'People should govern themselves', '(Example of) social contract']::text[], '[{"key":"popular-government","display":"Self-government","aliases":["Popular sovereignty","Consent of the governed","People should govern themselves"]},{"key":"social-contract","display":"Social contract","aliases":["(Example of) social contract"]}]'::jsonb, '[["The President governs without public consent"],["The people have no role in government"],["The Constitution is controlled by a monarch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, '“We the People” expresses popular self-government and consent. The distractors deny public authority or substitute rule by a monarch.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 5, 1, ARRAY['Amendments', 'The amendment process']::text[], '[{"key":"a1","display":"Amendments","aliases":[]},{"key":"a2","display":"The amendment process","aliases":["amendment process"]}]'::jsonb, '[["a presidential executive order"],["a Supreme Court ruling"],["an ordinary federal statute"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Constitutional changes are made through amendments; an executive order, court ruling, or ordinary statute is not an amendment.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 6, 1, ARRAY['(The basic) rights of Americans', '(The basic) rights of people living in the United States']::text[], '[{"key":"a1","display":"(The basic) rights of Americans","aliases":["rights of Americans","The basic rights of Americans"]},{"key":"a2","display":"(The basic) rights of people living in the United States","aliases":["rights of people living in the United States","The basic rights of people living in the United States"]}]'::jsonb, '[["the powers of Congress"],["the duties of state governors"],["the terms of federal judges"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Bill of Rights protects basic rights, not the powers of Congress, governor terms, or judicial terms.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 7, 1, ARRAY['Twenty-seven (27)']::text[], '[{"key":"a1","display":"Twenty-seven (27)","aliases":["27","Twenty-seven"]}]'::jsonb, '[["10"],["21"],["26"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution has 27 amendments; ten is the Bill of Rights count, not the total.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 8, 1, ARRAY['It says America is free from British control.', 'It says all people are created equal.', 'It identifies inherent rights.', 'It identifies individual freedoms.']::text[], '[{"key":"a1","display":"It says America is free from British control.","aliases":[]},{"key":"a2","display":"It says all people are created equal.","aliases":[]},{"key":"a3","display":"It identifies inherent rights.","aliases":[]},{"key":"a4","display":"It identifies individual freedoms.","aliases":[]}]'::jsonb, '[["It established a hereditary monarchy"],["It created the current federal government"],["It ended all disagreements between the states"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration states independence and inherent equality/rights; it did not establish a monarchy or create the later federal government.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 9, 1, ARRAY['Declaration of Independence']::text[], '[{"key":"a1","display":"Declaration of Independence","aliases":["the Declaration of Independence"]}]'::jsonb, '[["U.S. Constitution"],["Articles of Confederation"],["Federalist Papers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration of Independence declared the colonies free from Britain; the Constitution, Articles, and Federalist Papers serve different roles.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 10, 2, ARRAY['Equality', 'Liberty', 'Social contract', 'Natural rights', 'Limited government', 'Self-government']::text[], '[{"key":"a1","display":"Equality","aliases":[]},{"key":"a2","display":"Liberty","aliases":[]},{"key":"a3","display":"Social contract","aliases":[]},{"key":"a4","display":"Natural rights","aliases":[]},{"key":"a5","display":"Limited government","aliases":[]},{"key":"a6","display":"Self-government","aliases":[]}]'::jsonb, '[["divine right of kings","hereditary monarchy"],["unlimited royal power","aristocratic rule"],["state religion","absolute monarchy"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration and Constitution express equality, liberty, natural rights, social contract, limited government, and self-government. Divine-right monarchy and unlimited inherited authority contradict those principles.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 11, 1, ARRAY['Declaration of Independence']::text[], '[{"key":"a1","display":"Declaration of Independence","aliases":["the Declaration of Independence"]}]'::jsonb, '[["U.S. Constitution"],["Articles of Confederation"],["Federalist Papers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The phrase “Life, Liberty, and the pursuit of Happiness” is in the Declaration of Independence, not the other founding documents.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 12, 1, ARRAY['Capitalism', 'Free market economy']::text[], '[{"key":"a1","display":"Capitalism","aliases":[]},{"key":"a2","display":"Free market economy","aliases":[]}]'::jsonb, '[["command economy"],["feudal economy"],["barter-only economy"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. uses capitalism/free markets; command, feudal, and barter-only systems are different economic arrangements.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 13, 1, ARRAY['Everyone must follow the law.', 'Leaders must obey the law.', 'Government must obey the law.', 'No one is above the law.']::text[], '[{"key":"rule-of-law","display":"Everyone must follow the law","aliases":["Leaders must obey the law","Government must obey the law","No one is above the law"]}]'::jsonb, '[["The President is above the law"],["Only citizens must obey the law"],["Officials may ignore laws they dislike"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Rule of law means everyone, including leaders and government, must obey law; the distractors expressly exempt officials.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 14, 1, ARRAY['Declaration of Independence', 'Articles of Confederation', 'Federalist Papers', 'Anti-Federalist Papers', 'Virginia Declaration of Rights', 'Fundamental Orders of Connecticut', 'Mayflower Compact', 'Iroquois Great Law of Peace']::text[], '[{"key":"a1","display":"Declaration of Independence","aliases":[]},{"key":"a2","display":"Articles of Confederation","aliases":[]},{"key":"a3","display":"Federalist Papers","aliases":[]},{"key":"a4","display":"Anti-Federalist Papers","aliases":[]},{"key":"a5","display":"Virginia Declaration of Rights","aliases":[]},{"key":"a6","display":"Fundamental Orders of Connecticut","aliases":[]},{"key":"a7","display":"Mayflower Compact","aliases":[]},{"key":"a8","display":"Iroquois Great Law of Peace","aliases":[]}]'::jsonb, '[["Emancipation Proclamation"],["Gettysburg Address"],["Civil Rights Act of 1964"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The listed historical documents influenced the Constitution. The Emancipation Proclamation, Gettysburg Address, Civil Rights Act, and Federal Highway Act were later documents and did not influence its drafting.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 15, 1, ARRAY['So one part does not become too powerful', 'Checks and balances', 'Separation of powers']::text[], '[{"key":"checks-and-balances","display":"One part does not become too powerful","aliases":["So one part does not become too powerful","Checks and balances","Separation of powers"]}]'::jsonb, '[["to give one branch unlimited authority"],["to let the President write every law"],["to prevent the public from voting"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Branches prevent concentration of power through checks and balances and separation of powers; the distractors describe concentration or exclusion.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 16, 3, ARRAY['Legislative, executive, and judicial', 'Congress, president, and the courts']::text[], '[{"key":"legislative","display":"Legislative branch","aliases":["legislative","the legislative branch","Congress","Congress (legislative branch)"]},{"key":"executive","display":"Executive branch","aliases":["executive","the executive branch","President","president"]},{"key":"judicial","display":"Judicial branch","aliases":["judicial","the judicial branch","the courts","courts"]}]'::jsonb, '[["military","economic","diplomatic"],["state","local","military"],["economic","diplomatic","state"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The three constitutional branches are legislative, executive, and judicial. Military, economic, and diplomatic functions are not additional constitutional branches.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 17, 1, ARRAY['Executive branch']::text[], '[{"key":"a1","display":"Executive branch","aliases":[]}]'::jsonb, '[["Legislative branch"],["Judicial branch"],["Military branch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President leads the executive branch, not the legislative, judicial, or military organization.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 18, 1, ARRAY['(U.S.) Congress', '(U.S. or national) legislature', 'Legislative branch']::text[], '[{"key":"legislative","display":"Congress","aliases":["(U.S.) Congress","U.S. Congress","(U.S. or national) legislature","U.S. legislature","national legislature","Legislative branch","legislative branch"]}]'::jsonb, '[["the President"],["the Supreme Court"],["the Cabinet"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Congress and the legislative branch write federal laws; the President, Supreme Court, and Cabinet do not enact them.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 19, 2, ARRAY['Senate and House (of Representatives)']::text[], '[{"key":"senate","display":"Senate","aliases":["the Senate"]},{"key":"house","display":"House of Representatives","aliases":["House","the House of Representatives"]}]'::jsonb, '[["President","Cabinet"],["Supreme Court","federal courts"],["governor","state legislature"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Congress has two chambers, the Senate and House. The proposed pairs combine other government institutions that are not congressional chambers.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 20, 1, ARRAY['Writes laws', 'Declares war', 'Makes the federal budget']::text[], '[{"key":"a1","display":"Writes laws","aliases":[]},{"key":"a2","display":"Declares war","aliases":[]},{"key":"a3","display":"Makes the federal budget","aliases":[]}]'::jsonb, '[["vetoes bills"],["commands the military"],["decides whether laws are constitutional"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Congress writes laws, declares war, and sets the federal budget; vetoing, military command, and constitutional review belong elsewhere.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 21, 1, ARRAY['One hundred (100)']::text[], '[{"key":"a1","display":"One hundred (100)","aliases":["100","One hundred"]}]'::jsonb, '[["50"],["435"],["1,000"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'There are 100 U.S. senators; 50 is the state count and 435 is the House count.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 22, 1, ARRAY['Six (6) years']::text[], '[{"key":"a1","display":"Six (6) years","aliases":["6","Six","6 year","6 years","Six year","Six years"]}]'::jsonb, '[["two years"],["four years"],["eight years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A senator serves six years; two, four, and eight years are not the Senate term.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 23, 1, ARRAY[]::text[], '[]'::jsonb, '[["John R. Curtis"],["Lisa Murkowski"],["Cory Booker"],["Susan Collins"],["Tammy Duckworth"],["Ted Cruz"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The named people hold U.S. Senate seats for other states; none is a senator representing the selected state. Runtime adds and filters current senators from other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.senate.gov/general/resources/pdf/senators_phone_list.pdf', 'https://www.senate.gov/senators/Class_II.htm', 'https://www.senate.gov/senators/Class_III.htm', 'https://www.senate.gov/senators/AppointedSenators.htm']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 24, 1, ARRAY['Four hundred thirty-five (435)']::text[], '[{"key":"a1","display":"Four hundred thirty-five (435)","aliases":["435","Four hundred thirty-five"]}]'::jsonb, '[["100"],["50"],["500"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The House has 435 voting members; 100 is the Senate count and 50 is the number of states.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 25, 1, ARRAY['Two (2) years']::text[], '[{"key":"a1","display":"Two (2) years","aliases":["2","Two","2 year","2 years","Two year","Two years"]}]'::jsonb, '[["one year"],["four years"],["six years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A House term is two years; the other durations are not the House term.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 26, 1, ARRAY['To more closely follow public opinion']::text[], '[{"key":"a1","display":"To more closely follow public opinion","aliases":[]}]'::jsonb, '[["to insulate representatives from voters"],["because the House cannot pass laws"],["to give representatives lifetime terms"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'House members face voters more frequently, which lets representation follow public opinion more closely. The distractors claim the House cannot legislate or that members serve for life.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 27, 1, ARRAY['Two (2)']::text[], '[{"key":"a1","display":"Two (2)","aliases":["2","Two"]}]'::jsonb, '[["one"],["three"],["fifty"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Each state has two senators, not one, three, or fifty.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 28, 1, ARRAY['Equal representation (for small states)', 'The Great Compromise (Connecticut Compromise)']::text[], '[{"key":"equal-representation","display":"Equal representation for small states","aliases":["Equal representation","The Great Compromise","Connecticut Compromise"]}]'::jsonb, '[["to give larger states more Senate votes"],["because states have different populations"],["to let the President appoint half the senators"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Each state has two senators to provide equal state representation, including for smaller states; population does not set a state’s Senate seat count.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 29, 1, ARRAY[]::text[], '[]'::jsonb, '[["Mike Kennedy"],["Sarah McBride"],["Alexandria Ocasio-Cortez"],["Hakeem Jeffries"],["Brian Fitzpatrick"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The question asks for the representative of the selected district; a senator or governor is a different office.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://clerk.house.gov/xml/lists/MemberData.xml', 'https://clerk.house.gov/Members/ViewVacancies']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 30, 1, ARRAY[]::text[], '[]'::jsonb, '[["Nancy Pelosi"],["Paul Ryan"],["John Boehner"],["Kevin McCarthy"],["Newt Gingrich"],["Dennis Hastert"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'Mike Johnson is the current Speaker; the named former Speakers no longer hold that office.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 31, 1, ARRAY['Citizens of their state', 'People of their state']::text[], '[{"key":"state-constituents","display":"Citizens of their state","aliases":["People of their state"]}]'::jsonb, '[["the people of one congressional district"],["the people of the entire country"],["only the federal government"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A senator represents the citizens or people of their state, not one district or the entire nation.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 32, 1, ARRAY['Citizens from their state']::text[], '[{"key":"a1","display":"Citizens from their state","aliases":[]}]'::jsonb, '[["the state governor"],["the state legislature"],["the President"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'U.S. senators are elected by citizens of their state, not appointed by governors, legislatures, or the President.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 33, 1, ARRAY['Citizens in their (congressional) district', 'Citizens in their district', 'People from their (congressional) district', 'People in their district']::text[], '[{"key":"district-constituents","display":"Citizens in their congressional district","aliases":["Citizens in their district","People from their congressional district","People in their district"]}]'::jsonb, '[["citizens from another state"],["all citizens of the United States"],["the people of the whole state"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'A House member represents citizens/people in that congressional district, not people from another state or the whole country.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 34, 1, ARRAY['Citizens from their (congressional) district']::text[], '[{"key":"a1","display":"Citizens from their (congressional) district","aliases":["Citizens from their district","Citizens from their congressional district"]}]'::jsonb, '[["the state legislature"],["the President"],["the Senate"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Citizens of the district elect its House member; governors, Presidents, and the Senate do not elect that representative.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 35, 1, ARRAY['(Because of) the state’s population', '(Because) they have more people', '(Because) some states have more people']::text[], '[{"key":"population","display":"State population","aliases":["Because of the state’s population","Because they have more people","Because some states have more people"]}]'::jsonb, '[["the state’s land area"],["the state’s age"],["the number of counties in the state"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'House representation is apportioned by population; land area, age, and county count do not determine House seats.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 36, 1, ARRAY['Four (4) years']::text[], '[{"key":"a1","display":"Four (4) years","aliases":["4","Four","4 year","4 years","Four year","Four years"]}]'::jsonb, '[["two years"],["six years"],["eight years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President is elected for a four-year term; two, six, and eight years are incorrect durations.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 37, 1, ARRAY['(Because of) the 22nd Amendment', 'To keep the president from becoming too powerful']::text[], '[{"key":"a1","display":"(Because of) the 22nd Amendment","aliases":["the 22nd Amendment","Because of the 22nd Amendment","Twenty-second Amendment","22nd Amendment"]},{"key":"a2","display":"To keep the president from becoming too powerful","aliases":[]}]'::jsonb, '[["because of the 12th Amendment"],["because of the 25th Amendment"],["to keep the President in office longer"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Twenty-second Amendment limits presidential terms; the Twelfth and Twenty-fifth address different matters.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 38, 1, ARRAY[]::text[], '[]'::jsonb, '[["Joe Biden"],["Barack Obama"],["George W. Bush"],["Bill Clinton"],["George H. W. Bush"],["Ronald Reagan"],["Jimmy Carter"],["Gerald Ford"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named former Presidents no longer hold the current office; the active national answer row supplies the accepted current name and its reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 39, 1, ARRAY[]::text[], '[]'::jsonb, '[["Kamala Harris"],["Mike Pence"],["Tim Kaine"],["Joe Biden"],["Dick Cheney"],["Al Gore"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named people are former Vice Presidents; the active national answer row supplies only the current officeholder and reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 40, 1, ARRAY['The Vice President (of the United States)']::text[], '[{"key":"a1","display":"The Vice President (of the United States)","aliases":["The Vice President","Vice President (of the United States)","The Vice President of the United States","Vice President"]}]'::jsonb, '[["the Speaker of the House"],["the President pro tempore of the Senate"],["the Chief Justice"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Vice President is next in succession; the Speaker and other officers follow later, and the Chief Justice is not in the line.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 41, 1, ARRAY['Signs bills into law', 'Vetoes bills', 'Enforces laws', 'Commander in Chief (of the military)', 'Chief diplomat', 'Appoints federal judges']::text[], '[{"key":"a1","display":"Signs bills into law","aliases":[]},{"key":"a2","display":"Vetoes bills","aliases":[]},{"key":"a3","display":"Enforces laws","aliases":[]},{"key":"a4","display":"Commander in Chief (of the military)","aliases":["Commander in Chief","Commander in Chief of the military"]},{"key":"a5","display":"Chief diplomat","aliases":[]},{"key":"a6","display":"Appoints federal judges","aliases":[]}]'::jsonb, '[["writes federal statutes"],["declares war"],["decides whether a law is constitutional"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President signs/vetoes bills, enforces laws, commands the military, conducts diplomacy, and appoints judges; writing laws and declaring war are assigned elsewhere.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 42, 1, ARRAY['The President (of the United States)']::text[], '[{"key":"a1","display":"The President (of the United States)","aliases":["The President","President (of the United States)","The President of the United States","President"]}]'::jsonb, '[["the Secretary of Defense"],["the Speaker of the House"],["the Chairman of the Joint Chiefs of Staff"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President is Commander in Chief; military department and congressional leaders do not hold that constitutional role.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 43, 1, ARRAY['The President (of the United States)']::text[], '[{"key":"a1","display":"The President (of the United States)","aliases":["The President","President (of the United States)","The President of the United States","President"]}]'::jsonb, '[["the Speaker of the House"],["the Vice President"],["the Chief Justice"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President signs bills; the Speaker, Vice President, and Chief Justice do not sign them into law.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 44, 1, ARRAY['The President (of the United States)']::text[], '[{"key":"a1","display":"The President (of the United States)","aliases":["The President","President (of the United States)","The President of the United States","President"]}]'::jsonb, '[["Congress"],["the Vice President"],["the Supreme Court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President vetoes bills; Congress, Vice President, and Supreme Court do not exercise the presidential veto.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 45, 1, ARRAY['The President (of the United States)']::text[], '[{"key":"a1","display":"The President (of the United States)","aliases":["The President","President (of the United States)","The President of the United States","President"]}]'::jsonb, '[["the Senate"],["Congress"],["the Supreme Court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The President appoints federal judges, subject to Senate confirmation; the Senate does not originate the appointment.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 46, 1, ARRAY['President (of the United States)', 'Cabinet', 'Federal departments and agencies']::text[], '[{"key":"a1","display":"President (of the United States)","aliases":["President","President of the United States"]},{"key":"a2","display":"Cabinet","aliases":[]},{"key":"a3","display":"Federal departments and agencies","aliases":[]}]'::jsonb, '[["Congress"],["the Supreme Court"],["state legislatures"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The executive branch includes the President, Cabinet, and federal agencies; Congress, courts, and state legislatures are not its parts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 47, 1, ARRAY['Advises the President (of the United States)']::text[], '[{"key":"a1","display":"Advises the President (of the United States)","aliases":["Advises the President","Advises the President of the United States"]}]'::jsonb, '[["writes laws"],["commands the military"],["decides whether laws are constitutional"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Cabinet advises the President; it does not write laws, command the armed forces, or decide constitutionality.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 48, 2, ARRAY['Attorney General', 'Secretary of Agriculture', 'Secretary of Commerce', 'Secretary of Education', 'Secretary of Energy', 'Secretary of Health and Human Services', 'Secretary of Homeland Security', 'Secretary of Housing and Urban Development', 'Secretary of the Interior', 'Secretary of Labor', 'Secretary of State', 'Secretary of Transportation', 'Secretary of the Treasury', 'Secretary of Veterans Affairs', 'Secretary of War (Defense)', 'Vice-President', 'Administrator of the Environmental Protection Agency', 'Administrator of the Small Business Administration', 'Director of the Central Intelligence Agency', 'Director of the Office of Management and Budget', 'Director of National Intelligence', 'United States Trade Representative']::text[], '[{"key":"a1","display":"Attorney General","aliases":[]},{"key":"a2","display":"Secretary of Agriculture","aliases":[]},{"key":"a3","display":"Secretary of Commerce","aliases":[]},{"key":"a4","display":"Secretary of Education","aliases":[]},{"key":"a5","display":"Secretary of Energy","aliases":[]},{"key":"a6","display":"Secretary of Health and Human Services","aliases":[]},{"key":"a7","display":"Secretary of Homeland Security","aliases":[]},{"key":"a8","display":"Secretary of Housing and Urban Development","aliases":[]},{"key":"a9","display":"Secretary of the Interior","aliases":[]},{"key":"a10","display":"Secretary of Labor","aliases":[]},{"key":"a11","display":"Secretary of State","aliases":[]},{"key":"a12","display":"Secretary of Transportation","aliases":[]},{"key":"a13","display":"Secretary of the Treasury","aliases":[]},{"key":"a14","display":"Secretary of Veterans Affairs","aliases":[]},{"key":"secretary-defense","display":"Secretary of Defense","aliases":["Secretary of War","Secretary of War (Defense)","Defense Secretary"]},{"key":"a16","display":"Vice-President","aliases":[]},{"key":"a17","display":"Administrator of the Environmental Protection Agency","aliases":[]},{"key":"a18","display":"Administrator of the Small Business Administration","aliases":[]},{"key":"a19","display":"Director of the Central Intelligence Agency","aliases":[]},{"key":"a20","display":"Director of the Office of Management and Budget","aliases":[]},{"key":"a21","display":"Director of National Intelligence","aliases":[]},{"key":"a22","display":"United States Trade Representative","aliases":[]}]'::jsonb, '[["Deputy Secretary of State","White House Press Secretary"],["Assistant Secretary of the Treasury","Deputy Attorney General"],["Deputy Secretary of Defense","Deputy Secretary of Labor"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Cabinet-level positions are department heads and other principal officers. The listed deputy, press, and staff jobs are subordinate or support roles, not Cabinet-level posts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 49, 1, ARRAY['It decides who is elected president.', 'It provides a compromise between the popular election of the president and congressional selection.']::text[], '[{"key":"a1","display":"It decides who is elected president.","aliases":[]},{"key":"a2","display":"It provides a compromise between the popular election of the president and congressional selection.","aliases":[]}]'::jsonb, '[["It selects Supreme Court justices"],["It sets congressional districts"],["It approves constitutional amendments"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Electoral College participates in choosing the President; it does not appoint justices, draw districts, or amend the Constitution.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 50, 1, ARRAY['Supreme Court', 'Federal Courts']::text[], '[{"key":"a1","display":"Supreme Court","aliases":["the Supreme Court"]},{"key":"a2","display":"Federal Courts","aliases":[]}]'::jsonb, '[["Congress"],["the Cabinet"],["state police departments"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Supreme Court and federal courts are parts of the judicial branch; Congress, Cabinet, and police departments are not.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 51, 1, ARRAY['Reviews laws', 'Explains laws', 'Resolves disputes (disagreements) about the law', 'Decides if a law goes against the (U.S.) Constitution']::text[], '[{"key":"a1","display":"Reviews laws","aliases":[]},{"key":"a2","display":"Explains laws","aliases":[]},{"key":"a3","display":"Resolves disputes (disagreements) about the law","aliases":["Resolves disputes about the law","resolves disagreements about the law"]},{"key":"a4","display":"Decides if a law goes against the (U.S.) Constitution","aliases":["Decides if a law goes against the Constitution","Decides if a law goes against the U.S. Constitution"]}]'::jsonb, '[["writes bills"],["commands the armed forces"],["enforces every law"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The judiciary reviews/explains law, resolves disputes, and assesses constitutionality; legislating, commanding, and executing laws are other branches’ functions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 52, 1, ARRAY['Supreme Court']::text[], '[{"key":"a1","display":"Supreme Court","aliases":["the Supreme Court"]}]'::jsonb, '[["the U.S. Court of Appeals for the D.C. Circuit"],["a state supreme court"],["a federal district court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. Supreme Court is the highest court nationally; federal appellate, district, and state courts are lower in their respective systems.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 53, 1, ARRAY['Nine (9)']::text[], '[{"key":"a1","display":"Nine (9)","aliases":["9","Nine"]}]'::jsonb, '[["five"],["seven"],["eleven"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Supreme Court has nine seats; five, seven, and eleven are incorrect counts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 54, 1, ARRAY['Five (5)']::text[], '[{"key":"a1","display":"Five (5)","aliases":["5","Five"]}]'::jsonb, '[["four"],["six"],["nine"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Five justices are usually needed to decide a case; four, six, and nine are not the usual threshold.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 55, 1, ARRAY['(For) life', 'Lifetime appointment', '(Until) retirement']::text[], '[{"key":"a1","display":"(For) life","aliases":["life","For life"]},{"key":"a2","display":"Lifetime appointment","aliases":[]},{"key":"a3","display":"(Until) retirement","aliases":["retirement","Until retirement"]}]'::jsonb, '[["six years"],["twelve years"],["eighteen years"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Justices serve for life or until retirement; six-, twelve-, and eighteen-year terms would impose fixed terms.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 56, 1, ARRAY['To be independent (of politics)', 'To limit outside (political) influence']::text[], '[{"key":"a1","display":"To be independent (of politics)","aliases":["To be independent","To be independent of politics"]},{"key":"a2","display":"To limit outside (political) influence","aliases":["To limit outside influence","To limit outside political influence"]}]'::jsonb, '[["to follow public opinion"],["to make judges easier to remove"],["to limit judicial independence"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Life tenure protects judicial independence and limits outside political influence; the distractors describe the opposite purpose.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 57, 1, ARRAY[]::text[], '[]'::jsonb, '[["William Rehnquist"],["Warren Burger"],["Earl Warren"],["Harlan Fiske Stone"],["Charles Evans Hughes"],["John Marshall"],["Roger Taney"],["Salmon P. Chase"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"curated"}'::jsonb, 'The named people are former Chief Justices or other justices; the active national answer row supplies only the current Chief Justice and reviewed name variants.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.uscis.gov/citizenship/find-study-materials-and-resources/check-for-test-updates']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 58, 1, ARRAY['Print paper money', 'Mint coins', 'Declare war', 'Create an army', 'Make treaties', 'Set foreign policy']::text[], '[{"key":"a1","display":"Print paper money","aliases":[]},{"key":"a2","display":"Mint coins","aliases":[]},{"key":"a3","display":"Declare war","aliases":[]},{"key":"a4","display":"Create an army","aliases":[]},{"key":"a5","display":"Make treaties","aliases":[]},{"key":"a6","display":"Set foreign policy","aliases":[]}]'::jsonb, '[["issue a state driver license"],["approve a city zoning permit"],["issue a local building permit"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'State driver licensing, city zoning, and local building permits are state/local powers, not powers assigned only to the federal government.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 59, 1, ARRAY['Provide schooling and education', 'Provide protection (police)', 'Provide safety (fire departments)', 'Give a driver’s license', 'Approve zoning and land use']::text[], '[{"key":"a1","display":"Provide schooling and education","aliases":[]},{"key":"a2","display":"Provide protection (police)","aliases":["Provide protection","Provide protection police"]},{"key":"a3","display":"Provide safety (fire departments)","aliases":["Provide safety","Provide safety fire departments"]},{"key":"a4","display":"Give a driver’s license","aliases":[]},{"key":"a5","display":"Approve zoning and land use","aliases":[]}]'::jsonb, '[["declare war"],["make treaties"],["print paper money"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Declaring war, making treaties, and issuing national currency are federal powers, not state-only powers.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 60, 1, ARRAY['(It states that the) powers not given to the federal government belong to the states or to the people.']::text[], '[{"key":"a1","display":"(It states that the) powers not given to the federal government belong to the states or to the people.","aliases":["powers not given to the federal government belong to the states or to the people.","It states that the powers not given to the federal government belong to the states or to the people."]}]'::jsonb, '[["The federal government receives every remaining power"],["The amendment abolishes state governments"],["The amendment establishes a national religion"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Tenth Amendment reserves powers not delegated to the United States to the states or the people; it does not grant every power to the federal government or abolish states.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 61, 1, ARRAY[]::text[], '[]'::jsonb, '[["Gavin Newsom"],["Greg Abbott"],["Jared Polis"],["Spencer Cox"],["J.B. Pritzker"],["Sarah Huckabee Sanders"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"person_name","distractors":"other_geographies"}'::jsonb, 'The named people govern other states; none is governor of the selected state. Runtime adds and filters current governors from other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.nga.org/governors/']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 62, 1, ARRAY[]::text[], '[]'::jsonb, '[["Denver"],["Sacramento"],["Phoenix"],["Austin"],["Albany"],["Boston"]]'::jsonb, '{"answer_groups":"current_answer","current_aliases":"official_variants_only","distractors":"other_geographies"}'::jsonb, 'The named cities are capitals of other states, not the selected state’s capital. Runtime adds and filters capital values for the other jurisdictions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.lrl.mn.gov/docs/2013/other/130551.pdf', 'https://www.census.gov/content/dam/Census/library/publications/2015/demo/p23-213.pdf', 'https://www.mcog.guam.gov/villages-list?keyword=capital', 'https://home.treasury.gov/system/files/136/San-Juan-Municipio-Puerto-Rico_2024-Recovery-Plan_SLT-2215.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 63, 1, ARRAY['Citizens eighteen (18) and older (can vote).', 'You don’t have to pay (a poll tax) to vote.', 'Any citizen can vote. (Women and men can vote.)', 'A male citizen of any race (can vote).']::text[], '[{"key":"a1","display":"Citizens eighteen (18) and older (can vote).","aliases":["Citizens 18 and older.","Citizens eighteen and older.","Citizens 18 and older can vote.","Citizens eighteen and older can vote."]},{"key":"a2","display":"You don’t have to pay (a poll tax) to vote.","aliases":["You don’t have to pay to vote.","You don’t have to pay a poll tax to vote."]},{"key":"a3","display":"Any citizen can vote. (Women and men can vote.)","aliases":["Any citizen can vote.","Any citizen can vote. Women and men can vote."]},{"key":"a4","display":"A male citizen of any race (can vote).","aliases":["A male citizen of any race.","A male citizen of any race can vote.","male citizen of any race (can vote)."]}]'::jsonb, '[["Only landowners may vote"],["Only men may vote"],["Citizens must pay a poll tax to vote"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The voting amendments prohibit race- and sex-based exclusions and poll taxes, and protect voting rights for citizens at least 18. The proposed restrictions directly contradict those amendments.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 64, 1, ARRAY['Citizens', 'Citizens of the United States', 'U.S. citizens']::text[], '[{"key":"a1","display":"Citizens","aliases":[]},{"key":"a2","display":"Citizens of the United States","aliases":[]},{"key":"a3","display":"U.S. citizens","aliases":[]}]'::jsonb, '[["tourists"],["foreign corporations"],["people who have not become U.S. citizens"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The question asks who has the combined federal election, federal office, and jury eligibility identified in the study answer: U.S. citizens. Tourists, corporations, and noncitizens do not meet that description.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 65, 3, ARRAY['Freedom of expression', 'Freedom of speech', 'Freedom of assembly', 'Freedom to petition the government', 'Freedom of religion', 'The right to bear arms']::text[], '[{"key":"expression","display":"freedom of expression","aliases":["freedom of speech","speech"]},{"key":"assembly","display":"freedom of assembly","aliases":["assembly"]},{"key":"petition","display":"freedom to petition the government","aliases":["petition the government"]},{"key":"religion","display":"freedom of religion","aliases":["religion"]},{"key":"arms","display":"right to bear arms","aliases":["bear arms"]}]'::jsonb, '[["a right to require an official national religion","a right to silence peaceful criticism","a right to seize property"],["a right to prevent peaceful assembly","a right to control private beliefs","a right to censor newspapers"],["a right to ban petitions to government","a right to censor all newspapers","a right to ignore court orders"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The listed freedoms are rights of people living in the United States. The proposed powers to censor, impose religion, seize property, or ignore court orders are not such rights.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 66, 1, ARRAY['The United States', 'The flag']::text[], '[{"key":"pledge-loyalty","display":"The United States","aliases":["The flag","United States","flag"]}]'::jsonb, '[["the President"],["Congress"],["the Supreme Court"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Pledge expresses loyalty to the United States or its flag; it does not pledge allegiance to elected officials or a branch of government.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 67, 2, ARRAY['Give up loyalty to other countries', 'Defend the (U.S.) Constitution', 'Obey the laws of the United States', 'Serve in the military (if needed)', 'Serve (help, do important work for) the nation (if needed)', 'Be loyal to the United States']::text[], '[{"key":"a1","display":"Give up loyalty to other countries","aliases":[]},{"key":"a2","display":"Defend the (U.S.) Constitution","aliases":["Defend the Constitution","Defend the U.S. Constitution"]},{"key":"a3","display":"Obey the laws of the United States","aliases":[]},{"key":"a4","display":"Serve in the military (if needed)","aliases":["Serve in the military","Serve in the military if needed"]},{"key":"a5","display":"Serve (help, do important work for) the nation (if needed)","aliases":["Serve the nation","Serve the nation if needed","Serve help, do important work for the nation","Serve help, do important work for the nation if needed"]},{"key":"a6","display":"Be loyal to the United States","aliases":[]}]'::jsonb, '[["remain loyal to a foreign government","refuse to obey U.S. laws"],["reject the Constitution","avoid all civic duties"],["support a foreign monarch","violate U.S. law"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Oath promises loyalty to the United States, support for the Constitution and laws, and service if needed. The proposed promises reverse those commitments.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 68, 1, ARRAY['Be born in the United States, under the conditions set by the 14th Amendment', 'Naturalize', 'Derive citizenship (under conditions set by Congress)']::text[], '[{"key":"a1","display":"Be born in the United States, under the conditions set by the 14th Amendment","aliases":[]},{"key":"a2","display":"Naturalize","aliases":[]},{"key":"a3","display":"Derive citizenship (under conditions set by Congress)","aliases":["Derive citizenship","Derive citizenship under conditions set by Congress"]}]'::jsonb, '[["purchase citizenship without legal process"],["receive a state driver license"],["serve on a jury"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Citizenship is acquired by birth under constitutional conditions, naturalization, or derivation under law. A driver license or jury service does not confer citizenship.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 69, 2, ARRAY['Vote', 'Run for office', 'Join a political party', 'Help with a campaign', 'Join a civic group', 'Join a community group', 'Give an elected official your opinion (on an issue)', 'Contact elected officials', 'Support or oppose an issue or policy', 'Write to a newspaper']::text[], '[{"key":"a1","display":"Vote","aliases":[]},{"key":"a2","display":"Run for office","aliases":[]},{"key":"a3","display":"Join a political party","aliases":[]},{"key":"a4","display":"Help with a campaign","aliases":[]},{"key":"a5","display":"Join a civic group","aliases":[]},{"key":"a6","display":"Join a community group","aliases":[]},{"key":"a7","display":"Give an elected official your opinion (on an issue)","aliases":["Give an elected official your opinion","Give an elected official your opinion on an issue"]},{"key":"a8","display":"Contact elected officials","aliases":[]},{"key":"a9","display":"Support or oppose an issue or policy","aliases":[]},{"key":"a10","display":"Write to a newspaper","aliases":[]}]'::jsonb, '[["avoid public affairs","refuse to contact officials"],["ignore elections","prevent others from voting"],["refuse all community activity","avoid public meetings"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Voting, contacting officials, campaigning, and civic-group activity are forms of participation. Avoiding public affairs or obstructing voting is not participation.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 70, 1, ARRAY['Vote', 'Pay taxes', 'Obey the law', 'Serve in the military', 'Run for office', 'Work for local, state, or federal government']::text[], '[{"key":"a1","display":"Vote","aliases":[]},{"key":"a2","display":"Pay taxes","aliases":[]},{"key":"a3","display":"Obey the law","aliases":[]},{"key":"a4","display":"Serve in the military","aliases":[]},{"key":"a5","display":"Run for office","aliases":[]},{"key":"a6","display":"Work for local, state, or federal government","aliases":[]}]'::jsonb, '[["evade federal taxes"],["refuse lawful civic duties"],["damage public property"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Serving the country includes civic and public service. Evading taxes, refusing lawful duties, and damaging public property do not serve the country.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 71, 1, ARRAY['Required by law', 'All people pay to fund the federal government', 'Required by the (U.S.) Constitution (16th Amendment)', 'Civic duty']::text[], '[{"key":"a1","display":"Required by law","aliases":[]},{"key":"a2","display":"All people pay to fund the federal government","aliases":[]},{"key":"a3","display":"Required by the (U.S.) Constitution (16th Amendment)","aliases":["Required by the Constitution","Required by the U.S. Constitution","Required by the Constitution 16th Amendment","Required by the U.S. Constitution 16th Amendment"]},{"key":"a4","display":"Civic duty","aliases":[]}]'::jsonb, '[["because only state governments need money"],["because federal taxes are voluntary donations"],["because federal law forbids all private property"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Federal taxes are legally required and fund the federal government; the distractors wrongly limit the obligation or purpose.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 72, 1, ARRAY['Required by law', 'Civic duty', 'Makes the draft fair, if needed']::text[], '[{"key":"a1","display":"Required by law","aliases":[]},{"key":"a2","display":"Civic duty","aliases":[]},{"key":"a3","display":"Makes the draft fair, if needed","aliases":[]}]'::jsonb, '[["to receive automatic citizenship"],["to obtain routine employment"],["to avoid all federal taxes"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Selective Service registration is required by law, civic duty, and draft fairness; it does not grant citizenship, employment, or tax exemption.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 73, 1, ARRAY['Freedom', 'Political liberty', 'Religious freedom', 'Economic opportunity', 'Escape persecution']::text[], '[{"key":"a1","display":"Freedom","aliases":[]},{"key":"a2","display":"Political liberty","aliases":[]},{"key":"a3","display":"Religious freedom","aliases":[]},{"key":"a4","display":"Economic opportunity","aliases":[]},{"key":"a5","display":"Escape persecution","aliases":[]}]'::jsonb, '[["to join the 1849 California Gold Rush"],["to serve in the U.S. Peace Corps"],["to take part in the Apollo program"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The California Gold Rush, Peace Corps, and Apollo program arose long after colonial settlement; none could have motivated colonists to come to America.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 74, 1, ARRAY['American Indians', 'Native Americans']::text[], '[{"key":"a1","display":"American Indians","aliases":[]},{"key":"a2","display":"Native Americans","aliases":[]}]'::jsonb, '[["Spanish settlers"],["British colonists"],["French explorers"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Before European arrival, America was inhabited by American Indians/Native Americans; European settlers and explorers arrived later.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 75, 1, ARRAY['Africans', 'People from Africa']::text[], '[{"key":"a1","display":"Africans","aliases":[]},{"key":"a2","display":"People from Africa","aliases":[]}]'::jsonb, '[["British merchants"],["European colonists"],["people from Australia"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The answer identifies Africans forcibly transported and sold as slaves in America. The other groups are not the people described in the question.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 76, 1, ARRAY['American Revolution', 'The (American) Revolutionary War', 'War for (American) Independence']::text[], '[{"key":"a1","display":"American Revolution","aliases":[]},{"key":"a2","display":"The (American) Revolutionary War","aliases":["The Revolutionary War","(American) Revolutionary War","The American Revolutionary War"]},{"key":"a3","display":"War for (American) Independence","aliases":["War for Independence","War for American Independence"]}]'::jsonb, '[["the War of 1812"],["the Civil War"],["the French and Indian War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The American Revolution was the war for independence from Britain; the War of 1812 and Civil War had different causes and aims.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 77, 1, ARRAY['High taxes', 'Taxation without representation', 'British soldiers stayed in Americans’ houses (boarding, quartering)', 'They did not have self-government', 'Boston Massacre', 'Boston Tea Party (Tea Act)', 'Stamp Act', 'Sugar Act', 'Townshend Acts', 'Intolerable (Coercive) Acts']::text[], '[{"key":"a1","display":"High taxes","aliases":[]},{"key":"a2","display":"Taxation without representation","aliases":[]},{"key":"a3","display":"British soldiers stayed in Americans’ houses (boarding, quartering)","aliases":["British soldiers stayed in Americans’ houses"]},{"key":"a4","display":"They did not have self-government","aliases":[]},{"key":"a5","display":"Boston Massacre","aliases":[]},{"key":"a6","display":"Boston Tea Party (Tea Act)","aliases":["Boston Tea Party"]},{"key":"a7","display":"Stamp Act","aliases":[]},{"key":"a8","display":"Sugar Act","aliases":[]},{"key":"a9","display":"Townshend Acts","aliases":[]},{"key":"a10","display":"Intolerable (Coercive) Acts","aliases":["Intolerable Acts","Coercive Acts","Intolerable Acts"]}]'::jsonb, '[["because Britain granted full colonial self-government"],["to expand the power of the British monarchy"],["because colonists opposed religious liberty"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Taxation without representation, quartering, and lack of self-government were grievances; Britain did not grant the rights asserted in the distractors.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 78, 1, ARRAY['(Thomas) Jefferson']::text[], '[{"key":"a1","display":"(Thomas) Jefferson","aliases":["Jefferson","Thomas Jefferson"]}]'::jsonb, '[["George Washington"],["Alexander Hamilton"],["James Madison"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Thomas Jefferson wrote the Declaration; Washington, Hamilton, and Madison were not its author.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.archives.gov/founding-docs/declaration-history']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 79, 1, ARRAY['July 4, 1776']::text[], '[{"key":"a1","display":"July 4, 1776","aliases":["July 4th, 1776","4 July 1776","July Fourth, 1776"]}]'::jsonb, '[["July 2, 1776"],["July 4, 1787"],["June 4, 1776"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Declaration was adopted July 4, 1776; each distractor changes the exact month or year.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 80, 1, ARRAY['(Battle of) Bunker Hill', 'Declaration of Independence', 'Washington Crossing the Delaware (Battle of Trenton)', '(Battle of) Saratoga', 'Valley Forge (Encampment)', '(Battle of) Yorktown (British surrender at Yorktown)']::text[], '[{"key":"a1","display":"(Battle of) Bunker Hill","aliases":["Bunker Hill","Battle of Bunker Hill"]},{"key":"a2","display":"Declaration of Independence","aliases":[]},{"key":"a3","display":"Washington Crossing the Delaware (Battle of Trenton)","aliases":["Washington Crossing the Delaware","Washington Crossing the Delaware","Battle of Trenton"]},{"key":"a4","display":"(Battle of) Saratoga","aliases":["Saratoga","Battle of Saratoga"]},{"key":"a5","display":"Valley Forge (Encampment)","aliases":["Valley Forge","Valley Forge Encampment"]},{"key":"a6","display":"(Battle of) Yorktown (British surrender at Yorktown)","aliases":["Yorktown","Battle of Yorktown","Yorktown British surrender at Yorktown","Battle of Yorktown British surrender at Yorktown","British surrender at Yorktown"]}]'::jsonb, '[["the Battle of Gettysburg"],["the attack on Pearl Harbor"],["the Battle of Fort Sumter"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Revolution’s events include Bunker Hill, Saratoga, Trenton, and Yorktown; Gettysburg, Pearl Harbor, and Fort Sumter belong to other conflicts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 81, 5, ARRAY['New Hampshire', 'Massachusetts', 'Rhode Island', 'Connecticut', 'New York', 'New Jersey', 'Pennsylvania', 'Delaware', 'Maryland', 'Virginia', 'North Carolina', 'South Carolina', 'Georgia']::text[], '[{"key":"a1","display":"New Hampshire","aliases":[]},{"key":"a2","display":"Massachusetts","aliases":[]},{"key":"a3","display":"Rhode Island","aliases":[]},{"key":"a4","display":"Connecticut","aliases":[]},{"key":"a5","display":"New York","aliases":[]},{"key":"a6","display":"New Jersey","aliases":[]},{"key":"a7","display":"Pennsylvania","aliases":[]},{"key":"a8","display":"Delaware","aliases":[]},{"key":"a9","display":"Maryland","aliases":[]},{"key":"a10","display":"Virginia","aliases":[]},{"key":"a11","display":"North Carolina","aliases":[]},{"key":"a12","display":"South Carolina","aliases":[]},{"key":"a13","display":"Georgia","aliases":[]}]'::jsonb, '[["Ohio","Kentucky","Tennessee","Maine","Florida"],["Tennessee","Maine","Florida","California","Texas"],["Florida","California","Texas","Hawaii","Oregon"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The five selected states must come from the thirteen original states. Ohio, Kentucky, Tennessee, Maine, Florida, California, Texas, and Hawaii became states later.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 82, 1, ARRAY['(U.S.) Constitution']::text[], '[{"key":"a1","display":"(U.S.) Constitution","aliases":["Constitution","U.S. Constitution"]}]'::jsonb, '[["Articles of Confederation"],["Declaration of Independence"],["Bill of Rights"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Constitution was written in 1787. The Articles and Declaration predate it, while the Bill of Rights was ratified in 1791.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 83, 1, ARRAY['(James) Madison', '(Alexander) Hamilton', '(John) Jay', 'Publius']::text[], '[{"key":"a1","display":"(James) Madison","aliases":["Madison","James Madison"]},{"key":"a2","display":"(Alexander) Hamilton","aliases":["Hamilton","Alexander Hamilton"]},{"key":"a3","display":"(John) Jay","aliases":["Jay","John Jay"]},{"key":"a4","display":"Publius","aliases":[]}]'::jsonb, '[["Thomas Jefferson"],["John Adams"],["Patrick Henry"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Madison, Hamilton, and Jay wrote the Federalist Papers; Jefferson, Adams, and Henry were not among the named authors.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 84, 1, ARRAY['They helped people understand the (U.S.) Constitution.', 'They supported passing the (U.S.) Constitution.']::text[], '[{"key":"a1","display":"They helped people understand the (U.S.) Constitution.","aliases":["They helped people understand the Constitution.","They helped people understand the U.S. Constitution."]},{"key":"a2","display":"They supported passing the (U.S.) Constitution.","aliases":["They supported passing the Constitution.","They supported passing the U.S. Constitution."]}]'::jsonb, '[["They opposed ratification of the Constitution"],["They were amendments to the Constitution"],["They were written by the President"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Federalist Papers explained and supported ratification; they were not amendments, anti-ratification essays, or presidential writings.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 85, 1, ARRAY['Founded the first free public libraries', 'First Postmaster General of the United States', 'Helped write the Declaration of Independence', 'Inventor', 'U.S. diplomat']::text[], '[{"key":"a1","display":"Founded the first free public libraries","aliases":[]},{"key":"a2","display":"First Postmaster General of the United States","aliases":[]},{"key":"a3","display":"Helped write the Declaration of Independence","aliases":[]},{"key":"a4","display":"Inventor","aliases":[]},{"key":"a5","display":"U.S. diplomat","aliases":[]}]'::jsonb, '[["commanded the Continental Army"],["was the first U.S. President"],["delivered the Gettysburg Address"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Franklin’s listed achievements include public libraries, postmaster service, diplomacy, and inventions; command of the Continental Army and the first presidency were Washington’s, and Lincoln delivered the Gettysburg Address.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 86, 1, ARRAY['“Father of Our Country”', 'First president of the United States', 'General of the Continental Army', 'President of the Constitutional Convention']::text[], '[{"key":"a1","display":"“Father of Our Country”","aliases":[]},{"key":"a2","display":"First president of the United States","aliases":[]},{"key":"a3","display":"General of the Continental Army","aliases":[]},{"key":"a4","display":"President of the Constitutional Convention","aliases":[]}]'::jsonb, '[["wrote the Declaration of Independence"],["was the 16th President"],["founded the first free public library"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Washington was Father of Our Country, first President, Continental Army general, and Convention president; the distractors assign other founders’ achievements.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 87, 1, ARRAY['Writer of the Declaration of Independence', 'Third president of the United States', 'Doubled the size of the United States (Louisiana Purchase)', 'First Secretary of State', 'Founded the University of Virginia', 'Writer of the Virginia Statute on Religious Freedom']::text[], '[{"key":"a1","display":"Writer of the Declaration of Independence","aliases":[]},{"key":"a2","display":"Third president of the United States","aliases":[]},{"key":"a3","display":"Doubled the size of the United States (Louisiana Purchase)","aliases":["Doubled the size of the United States","Louisiana Purchase"]},{"key":"a4","display":"First Secretary of State","aliases":[]},{"key":"a5","display":"Founded the University of Virginia","aliases":[]},{"key":"a6","display":"Writer of the Virginia Statute on Religious Freedom","aliases":[]}]'::jsonb, '[["was the first U.S. President"],["was the “Father of the Constitution”"],["led the civil rights movement"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Jefferson wrote the Declaration, was third President, and made the Louisiana Purchase; the alternatives identify Washington, Madison, and King.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 88, 1, ARRAY['“Father of the Constitution”', 'Fourth president of the United States', 'President during the War of 1812', 'One of the writers of the Federalist Papers']::text[], '[{"key":"a1","display":"“Father of the Constitution”","aliases":[]},{"key":"a2","display":"Fourth president of the United States","aliases":[]},{"key":"a3","display":"President during the War of 1812","aliases":[]},{"key":"a4","display":"One of the writers of the Federalist Papers","aliases":[]}]'::jsonb, '[["was the first U.S. President"],["commanded the Continental Army"],["wrote the Declaration of Independence"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Madison was Father of the Constitution, fourth President, War of 1812 President, and Federalist writer; the alternatives describe other founders.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 89, 1, ARRAY['First Secretary of the Treasury', 'One of the writers of the Federalist Papers', 'Helped establish the First Bank of the United States', 'Aide to General George Washington', 'Member of the Continental Congress']::text[], '[{"key":"a1","display":"First Secretary of the Treasury","aliases":[]},{"key":"a2","display":"One of the writers of the Federalist Papers","aliases":[]},{"key":"a3","display":"Helped establish the First Bank of the United States","aliases":[]},{"key":"a4","display":"Aide to General George Washington","aliases":[]},{"key":"a5","display":"Member of the Continental Congress","aliases":[]}]'::jsonb, '[["was President during the Civil War"],["wrote the Declaration of Independence"],["was the “Father of Our Country”"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Hamilton served as Treasury Secretary, Federalist writer, bank founder, and Washington aide; the distractors assign him other founders’ roles.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 90, 1, ARRAY['Louisiana Territory', 'Louisiana']::text[], '[{"key":"a1","display":"Louisiana Territory","aliases":[]},{"key":"a2","display":"Louisiana","aliases":[]}]'::jsonb, '[["Florida Territory"],["Oregon Country"],["Alaska"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Louisiana Purchase was territory acquired from France in 1803; Florida, Oregon, and Alaska came from other acquisitions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 91, 1, ARRAY['War of 1812', 'Mexican-American War', 'Civil War', 'Spanish-American War']::text[], '[{"key":"a1","display":"War of 1812","aliases":[]},{"key":"a2","display":"Mexican-American War","aliases":[]},{"key":"a3","display":"Civil War","aliases":[]},{"key":"a4","display":"Spanish-American War","aliases":[]}]'::jsonb, '[["World War I"],["World War II"],["Korean War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The requested conflicts occurred in the 1800s; the world wars and Korean War occurred in the 1900s.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 92, 1, ARRAY['The Civil War']::text[], '[{"key":"a1","display":"The Civil War","aliases":["Civil War"]}]'::jsonb, '[["War of 1812"],["Mexican-American War"],["Spanish-American War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Civil War was the North–South war; the other wars had different opponents and periods.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 93, 1, ARRAY['(Battle of) Fort Sumter', 'Emancipation Proclamation', '(Battle of) Vicksburg', '(Battle of) Gettysburg', 'Sherman’s March', '(Surrender at) Appomattox', '(Battle of) Antietam/Sharpsburg', 'Lincoln was assassinated.']::text[], '[{"key":"a1","display":"(Battle of) Fort Sumter","aliases":["Fort Sumter","Battle of Fort Sumter"]},{"key":"a2","display":"Emancipation Proclamation","aliases":[]},{"key":"a3","display":"(Battle of) Vicksburg","aliases":["Vicksburg","Battle of Vicksburg"]},{"key":"a4","display":"(Battle of) Gettysburg","aliases":["Gettysburg","Battle of Gettysburg"]},{"key":"a5","display":"Sherman’s March","aliases":[]},{"key":"a6","display":"(Surrender at) Appomattox","aliases":["Appomattox","Surrender at Appomattox"]},{"key":"a7","display":"(Battle of) Antietam/Sharpsburg","aliases":["Antietam/Sharpsburg","Battle of Antietam/Sharpsburg","Antietam","Sharpsburg","Battle of Antietam","Battle of Sharpsburg"]},{"key":"a8","display":"Lincoln was assassinated.","aliases":[]}]'::jsonb, '[["the Battle of Trenton"],["the Battle of the Bulge"],["the Battle of Midway"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Battle of Trenton was in the Revolution, and Midway and the Bulge were World War II battles; none was a Civil War event.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://www.nps.gov/civilwar/search-battles-detail.htm?battleCode=LA002']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 94, 1, ARRAY['Freed the slaves (Emancipation Proclamation)', 'Saved (or preserved) the Union', 'Led the United States during the Civil War', '16th president of the United States', 'Delivered the Gettysburg Address']::text[], '[{"key":"a1","display":"Freed the slaves (Emancipation Proclamation)","aliases":["Freed the slaves","Emancipation Proclamation"]},{"key":"a2","display":"Saved (or preserved) the Union","aliases":["Saved the Union","preserved the Union","Saved or preserved the Union"]},{"key":"a3","display":"Led the United States during the Civil War","aliases":[]},{"key":"a4","display":"16th president of the United States","aliases":[]},{"key":"a5","display":"Delivered the Gettysburg Address","aliases":[]}]'::jsonb, '[["was the first President"],["wrote the Declaration of Independence"],["commanded the Continental Army in the Revolution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Lincoln freed enslaved people, preserved the Union, led during the Civil War, and delivered the Gettysburg Address; the alternatives identify other founders.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 95, 1, ARRAY['Freed the slaves', 'Freed slaves in the Confederacy', 'Freed slaves in the Confederate states', 'Freed slaves in most Southern states']::text[], '[{"key":"a1","display":"Freed the slaves","aliases":[]},{"key":"a2","display":"Freed slaves in the Confederacy","aliases":[]},{"key":"a3","display":"Freed slaves in the Confederate states","aliases":[]},{"key":"a4","display":"Freed slaves in most Southern states","aliases":[]}]'::jsonb, '[["freed enslaved people in every country"],["ended slavery in Union states"],["granted women the right to vote"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Proclamation freed enslaved people in rebelling Confederate areas, not worldwide, in loyal Union states, or by granting suffrage.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 96, 1, ARRAY['The Civil War']::text[], '[{"key":"a1","display":"The Civil War","aliases":["Civil War"]}]'::jsonb, '[["World War I"],["War of 1812"],["the American Revolution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Civil War ended slavery; the Revolution, War of 1812, and World War I did not.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 97, 1, ARRAY['14th Amendment']::text[], '[{"key":"a1","display":"14th Amendment","aliases":["Fourteenth Amendment","14th"]}]'::jsonb, '[["15th Amendment"],["19th Amendment"],["10th Amendment"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Fourteenth Amendment defines citizenship for persons born or naturalized in the United States; the Fifteenth, Nineteenth, and Tenth Amendments address different subjects.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 98, 1, ARRAY['After the Civil War', 'During Reconstruction', '(With the) 15th Amendment', '1870']::text[], '[{"key":"a1","display":"After the Civil War","aliases":[]},{"key":"a2","display":"During Reconstruction","aliases":[]},{"key":"a3","display":"(With the) 15th Amendment","aliases":["15th Amendment","With the 15th Amendment","Fifteenth Amendment","15th"]},{"key":"a4","display":"1870","aliases":[]}]'::jsonb, '[["1776"],["1787"],["1861"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Fifteenth Amendment and Reconstruction established voting rights for men regardless of race after the Civil War; 1776, 1787, and 1861 all predate that amendment.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 99, 1, ARRAY['Susan B. Anthony', 'Elizabeth Cady Stanton', 'Sojourner Truth', 'Harriet Tubman', 'Lucretia Mott', 'Lucy Stone']::text[], '[{"key":"a1","display":"Susan B. Anthony","aliases":[]},{"key":"a2","display":"Elizabeth Cady Stanton","aliases":[]},{"key":"a3","display":"Sojourner Truth","aliases":[]},{"key":"a4","display":"Harriet Tubman","aliases":[]},{"key":"a5","display":"Lucretia Mott","aliases":[]},{"key":"a6","display":"Lucy Stone","aliases":[]}]'::jsonb, '[["Amelia Earhart"],["Eleanor Roosevelt"],["Rosa Parks"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The question asks for 19th-century women’s rights leaders; the alternatives are 20th-century public figures.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 100, 1, ARRAY['World War I', 'World War II', 'Korean War', 'Vietnam War', '(Persian) Gulf War']::text[], '[{"key":"a1","display":"World War I","aliases":["WWI","World War One","First World War"]},{"key":"a2","display":"World War II","aliases":["WWII","World War Two","Second World War"]},{"key":"a3","display":"Korean War","aliases":[]},{"key":"a4","display":"Vietnam War","aliases":[]},{"key":"a5","display":"(Persian) Gulf War","aliases":["Gulf War","Persian Gulf War"]}]'::jsonb, '[["the American Revolution"],["the Civil War"],["the War of 1812"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The listed conflicts are from the 1900s; the Revolution, Civil War, and War of 1812 occurred earlier.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 101, 1, ARRAY['Because Germany attacked U.S. (civilian) ships', 'To support the Allied Powers (England, France, Italy, and Russia)', 'To oppose the Central Powers (Germany, Austria-Hungary, the Ottoman Empire, and Bulgaria)']::text[], '[{"key":"a1","display":"Because Germany attacked U.S. (civilian) ships","aliases":["Because Germany attacked U.S. ships","Because Germany attacked U.S. civilian ships"]},{"key":"a2","display":"To support the Allied Powers (England, France, Italy, and Russia)","aliases":["To support the Allied Powers","To support the Allied Powers England, France, Italy, and Russia"]},{"key":"a3","display":"To oppose the Central Powers (Germany, Austria-Hungary, the Ottoman Empire, and Bulgaria)","aliases":["To oppose the Central Powers","To oppose the Central Powers Germany, Austria-Hungary, the Ottoman Empire, and Bulgaria"]}]'::jsonb, '[["because of the attack on Pearl Harbor"],["to force Iraq out of Kuwait"],["to respond to the attack on Fort Sumter"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. entered World War I after German attacks and to support the Allies/oppose Central Powers; Pearl Harbor and the other wars are unrelated.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 102, 1, ARRAY['1920', 'After World War I', '(With the) 19th Amendment']::text[], '[{"key":"a1","display":"1920","aliases":[]},{"key":"a2","display":"After World War I","aliases":[]},{"key":"a3","display":"(With the) 19th Amendment","aliases":["19th Amendment","With the 19th Amendment","Nineteenth Amendment","19th"]}]'::jsonb, '[["1776"],["1787"],["1861"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Women gained constitutional voting protection in 1920 under the Nineteenth Amendment; 1776, 1787, and 1861 all predate that protection.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 103, 1, ARRAY['Longest economic recession in modern history']::text[], '[{"key":"a1","display":"Longest economic recession in modern history","aliases":[]}]'::jsonb, '[["a period of rapid economic growth"],["a constitutional amendment"],["a military conflict"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Great Depression was a severe, prolonged economic downturn, not a war, constitutional amendment, or period of rapid growth.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 104, 1, ARRAY['The Great Crash (1929)', 'Stock market crash of 1929']::text[], '[{"key":"a1","display":"The Great Crash (1929)","aliases":["The Great Crash","Great Crash (1929)","1929"]},{"key":"a2","display":"Stock market crash of 1929","aliases":[]}]'::jsonb, '[["1918"],["1945"],["2008"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Great Depression began with the 1929 crash; 1918, 1945, and 2008 are different dates/crises.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 105, 1, ARRAY['(Franklin) Roosevelt']::text[], '[{"key":"a1","display":"(Franklin) Roosevelt","aliases":["Roosevelt","Franklin Roosevelt"]}]'::jsonb, '[["Herbert Hoover"],["Harry Truman"],["Woodrow Wilson"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Franklin Roosevelt was President during the Great Depression and World War II; Hoover, Truman, and Wilson do not span both.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 106, 1, ARRAY['(Bombing of) Pearl Harbor', 'Japanese attacked Pearl Harbor', 'To support the Allied Powers (England, France, and Russia)', 'To oppose the Axis Powers (Germany, Italy, and Japan)']::text[], '[{"key":"a1","display":"(Bombing of) Pearl Harbor","aliases":["Pearl Harbor","Bombing of Pearl Harbor"]},{"key":"a2","display":"Japanese attacked Pearl Harbor","aliases":[]},{"key":"a3","display":"To support the Allied Powers (England, France, and Russia)","aliases":["To support the Allied Powers","To support the Allied Powers England, France, and Russia"]},{"key":"a4","display":"To oppose the Axis Powers (Germany, Italy, and Japan)","aliases":["To oppose the Axis Powers","To oppose the Axis Powers Germany, Italy, and Japan"]}]'::jsonb, '[["Germany attacked Pearl Harbor"],["the United States entered to free Kuwait"],["the United States entered to fight in Korea"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The United States entered World War II after Japan attacked Pearl Harbor and through its conflict with the Axis; the distractors mix causes from other wars.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 107, 1, ARRAY['General during World War II', 'President at the end of (during) the Korean War', '34th president of the United States', 'Signed the Federal-Aid Highway Act of 1956 (Created the Interstate System)']::text[], '[{"key":"a1","display":"General during World War II","aliases":[]},{"key":"a2","display":"President at the end of (during) the Korean War","aliases":["President at the end of the Korean War","President during the Korean War"]},{"key":"a3","display":"34th president of the United States","aliases":[]},{"key":"a4","display":"Signed the Federal-Aid Highway Act of 1956 (Created the Interstate System)","aliases":["Signed the Federal-Aid Highway Act of 1956","Signed the Federal-Aid Highway Act of 1956 Created the Interstate System","Created the Interstate System","Interstate System"]}]'::jsonb, '[["wrote the Declaration of Independence"],["was the first President"],["led the Continental Army in the Revolution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Eisenhower was a World War II general and later President; the distractors assign him achievements of Jefferson and Washington.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 108, 1, ARRAY['Soviet Union', 'USSR', 'Russia']::text[], '[{"key":"a1","display":"Soviet Union","aliases":[]},{"key":"a2","display":"USSR","aliases":[]},{"key":"a3","display":"Russia","aliases":[]}]'::jsonb, '[["United Kingdom"],["France"],["Canada"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Soviet Union was the main Cold War rival; Britain, France, and Canada were U.S. allies.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 109, 1, ARRAY['Communism', 'Nuclear war']::text[], '[{"key":"a1","display":"Communism","aliases":[]},{"key":"a2","display":"Nuclear war","aliases":[]}]'::jsonb, '[["restoring feudalism"],["piracy"],["the American Civil War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The question concerns U.S. Cold War priorities; restoring feudalism, piracy, and the American Civil War are not Cold War concerns.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 110, 1, ARRAY['To stop the spread of communism']::text[], '[{"key":"a1","display":"To stop the spread of communism","aliases":[]}]'::jsonb, '[["to force Iraq out of Kuwait"],["to respond to Pearl Harbor"],["to stop the spread of fascism in Germany"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The U.S. entered the Korean War to stop communism’s spread; Iraq/Kuwait and Pearl Harbor are different conflicts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 111, 1, ARRAY['To stop the spread of communism']::text[], '[{"key":"a1","display":"To stop the spread of communism","aliases":[]}]'::jsonb, '[["to force Iraq out of Kuwait"],["to respond to the invasion of South Korea"],["to capture Osama bin Laden"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The stated U.S. rationale for entering Vietnam was containing communism; the distractors refer to the Gulf War, Korea, and post-9/11 operations.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 112, 1, ARRAY['Fought to end racial discrimination']::text[], '[{"key":"a1","display":"Fought to end racial discrimination","aliases":[]}]'::jsonb, '[["expanded racial segregation"],["restored slavery"],["limited equal protection under law"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The civil rights movement fought racial discrimination; the distractors describe extending discrimination or slavery.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 113, 1, ARRAY['Fought for civil rights', 'Worked for equality for all Americans', 'Worked to ensure that people would “not be judged by the color of their skin, but by the content of their character”']::text[], '[{"key":"a1","display":"Fought for civil rights","aliases":[]},{"key":"a2","display":"Worked for equality for all Americans","aliases":[]},{"key":"a3","display":"Worked to ensure that people would “not be judged by the color of their skin, but by the content of their character”","aliases":[]}]'::jsonb, '[["was the first U.S. President"],["commanded the Continental Army"],["wrote the Declaration of Independence"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'King’s recognized work was civil rights and equality; the distractors assign him roles associated with Washington, Jefferson, or Franklin.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 114, 1, ARRAY['To force the Iraqi military from Kuwait']::text[], '[{"key":"a1","display":"To force the Iraqi military from Kuwait","aliases":[]}]'::jsonb, '[["to reunite North and South Korea"],["to remove Japan from China"],["to defend Pearl Harbor"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Persian Gulf War response forced Iraqi forces out of Kuwait; Korea, China, and Pearl Harbor refer to different conflicts.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 115, 1, ARRAY['Terrorists attacked the United States', 'Terrorists took over two planes and crashed them into the World Trade Center in New York City', 'Terrorists took over a plane and crashed into the Pentagon in Arlington, Virginia', 'Terrorists took over a plane originally aimed at Washington, D.C., and crashed in a field in Pennsylvania']::text[], '[{"key":"a1","display":"Terrorists attacked the United States","aliases":[]},{"key":"a2","display":"Terrorists took over two planes and crashed them into the World Trade Center in New York City","aliases":[]},{"key":"a3","display":"Terrorists took over a plane and crashed into the Pentagon in Arlington, Virginia","aliases":[]},{"key":"a4","display":"Terrorists took over a plane originally aimed at Washington, D.C., and crashed in a field in Pennsylvania","aliases":[]}]'::jsonb, '[["the Moon landing"],["the attack on Pearl Harbor"],["the end of World War II"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'September 11, 2001 was the terrorist attack on the United States; the other choices occurred at different times.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 116, 1, ARRAY['(Global) War on Terror', 'War in Afghanistan', 'War in Iraq']::text[], '[{"key":"a1","display":"(Global) War on Terror","aliases":["War on Terror","Global War on Terror"]},{"key":"a2","display":"War in Afghanistan","aliases":[]},{"key":"a3","display":"War in Iraq","aliases":[]}]'::jsonb, '[["the Korean War"],["the Vietnam War"],["the Persian Gulf War (1990–1991)"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The accepted examples are conflicts after September 11, 2001. Korea, Vietnam, and the 1990–1991 Persian Gulf War all predate those attacks.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 117, 1, ARRAY['Apache', 'Blackfeet', 'Cayuga', 'Cherokee', 'Cheyenne', 'Chippewa', 'Choctaw', 'Creek', 'Crow', 'Hopi', 'Huron', 'Inupiat', 'Lakota', 'Mohawk', 'Mohegan', 'Navajo', 'Oneida', 'Onondaga', 'Pueblo', 'Seminole', 'Seneca', 'Shawnee', 'Sioux', 'Teton', 'Tuscarora']::text[], '[{"key":"a1","display":"Apache","aliases":[]},{"key":"a2","display":"Blackfeet","aliases":[]},{"key":"a3","display":"Cayuga","aliases":[]},{"key":"a4","display":"Cherokee","aliases":[]},{"key":"a5","display":"Cheyenne","aliases":[]},{"key":"a6","display":"Chippewa","aliases":[]},{"key":"a7","display":"Choctaw","aliases":[]},{"key":"a8","display":"Creek","aliases":[]},{"key":"a9","display":"Crow","aliases":[]},{"key":"a10","display":"Hopi","aliases":[]},{"key":"a11","display":"Huron","aliases":[]},{"key":"a12","display":"Inupiat","aliases":[]},{"key":"a13","display":"Lakota","aliases":[]},{"key":"a14","display":"Mohawk","aliases":[]},{"key":"a15","display":"Mohegan","aliases":[]},{"key":"a16","display":"Navajo","aliases":[]},{"key":"a17","display":"Oneida","aliases":[]},{"key":"a18","display":"Onondaga","aliases":[]},{"key":"a19","display":"Pueblo","aliases":[]},{"key":"a20","display":"Seminole","aliases":[]},{"key":"a21","display":"Seneca","aliases":[]},{"key":"a22","display":"Shawnee","aliases":[]},{"key":"a23","display":"Sioux","aliases":[]},{"key":"a24","display":"Teton","aliases":[]},{"key":"a25","display":"Tuscarora","aliases":[]}]'::jsonb, '[["Amish"],["Cajun"],["Pennsylvania Dutch"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Amish, Cajun, and Pennsylvania Dutch communities are not American Indian tribes; each is a different cultural or religious community.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 118, 1, ARRAY['Light bulb', 'Automobile (cars, internal combustion engine)', 'Skyscrapers', 'Airplane', 'Assembly line', 'Landing on the moon', 'Integrated circuit (IC)']::text[], '[{"key":"a1","display":"Light bulb","aliases":[]},{"key":"a2","display":"Automobile (cars, internal combustion engine)","aliases":["cars","Automobile","internal combustion engine"]},{"key":"a3","display":"Skyscrapers","aliases":[]},{"key":"a4","display":"Airplane","aliases":[]},{"key":"a5","display":"Assembly line","aliases":[]},{"key":"a6","display":"Landing on the moon","aliases":[]},{"key":"a7","display":"Integrated circuit (IC)","aliases":["Integrated circuit","IC"]}]'::jsonb, '[["paper"],["the compass"],["gunpowder"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Paper, the compass, and gunpowder originated in China, so they are not American innovations. The linked Smithsonian source documents their Chinese origins.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf', 'https://asia-archive.si.edu/learn/for-educators/teaching-china-with-the-smithsonian/explore-by-theme/production-and-technology/', 'https://airandspace.si.edu/stories/editorial/first-fireworks-origins-rocket']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 119, 1, ARRAY['Washington, D.C.']::text[], '[{"key":"a1","display":"Washington, D.C.","aliases":["Washington DC","Washington D.C.","Washington D C"]}]'::jsonb, '[["Philadelphia"],["New York City"],["Boston"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Washington, D.C. is the U.S. capital; Philadelphia, New York, and Boston are not the current national capital.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 120, 1, ARRAY['New York (Harbor)', 'Liberty Island', 'New Jersey', 'near New York City', 'on the Hudson (River)']::text[], '[{"key":"a1","display":"New York (Harbor)","aliases":["New York","New York Harbor"]},{"key":"a2","display":"Liberty Island","aliases":[]},{"key":"a3","display":"New Jersey","aliases":[]},{"key":"a4","display":"near New York City","aliases":[]},{"key":"a5","display":"on the Hudson (River)","aliases":["on the Hudson","on the Hudson River"]}]'::jsonb, '[["Boston Harbor, Massachusetts"],["Potomac River, Virginia"],["San Francisco Bay, California"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The Statue of Liberty is in New York Harbor/Liberty Island; the distractors place it in other regions.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 121, 1, ARRAY['(Because there were) 13 original colonies', '(Because the stripes) represent the original colonies']::text[], '[{"key":"a1","display":"(Because there were) 13 original colonies","aliases":["13 original colonies","Because there were 13 original colonies"]},{"key":"a2","display":"(Because the stripes) represent the original colonies","aliases":["represent the original colonies","Because the stripes represent the original colonies"]}]'::jsonb, '[["the 50 states"],["the first 13 amendments"],["the 13 Presidents"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The thirteen stripes represent the original colonies, not states, amendments, or Presidents.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 122, 1, ARRAY['(Because there is) one star for each state', '(Because) each star represents a state', '(Because there are) 50 states']::text[], '[{"key":"a1","display":"(Because there is) one star for each state","aliases":["one star for each state","Because there is one star for each state"]},{"key":"a2","display":"(Because) each star represents a state","aliases":["each star represents a state","Because each star represents a state"]},{"key":"a3","display":"(Because there are) 50 states","aliases":["50 states","Because there are 50 states"]}]'::jsonb, '[["the 13 original colonies"],["one star for each U.S. territory"],["the 50 original states"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The fifty stars represent the fifty states; the original colonies numbered thirteen and U.S. territories do not each have a flag star.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 123, 1, ARRAY['The Star-Spangled Banner']::text[], '[{"key":"a1","display":"The Star-Spangled Banner","aliases":["Star-Spangled Banner"]}]'::jsonb, '[["America the Beautiful"],["My Country, ’Tis of Thee"],["God Bless America"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The national anthem is “The Star-Spangled Banner”; the alternatives are other patriotic songs or symbols.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 124, 1, ARRAY['Out of many, one', 'We all become one']::text[], '[{"key":"out-of-many-one","display":"Out of many, one","aliases":["We all become one"]}]'::jsonb, '[["from one, many separate parts"],["everyone remains separate"],["many become many, not one"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, '“E Pluribus Unum” means “Out of many, one.” The distractors reverse that relationship or replace the Latin motto with a different idea.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 125, 1, ARRAY['A holiday to celebrate U.S. independence (from Britain)', 'The country’s birthday']::text[], '[{"key":"a1","display":"A holiday to celebrate U.S. independence (from Britain)","aliases":["A holiday to celebrate U.S. independence","A holiday to celebrate U.S. independence from Britain","holiday to celebrate U.S. independence (from Britain)"]},{"key":"a2","display":"The country’s birthday","aliases":["country’s birthday"]}]'::jsonb, '[["a holiday honoring military veterans"],["a holiday commemorating the Constitution"],["a holiday marking the end of the Civil War"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Independence Day celebrates independence from Britain and the country’s birthday; the distractors describe other commemorations.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 126, 3, ARRAY['New Year’s Day', 'Martin Luther King, Jr. Day', 'Presidents Day (Washington’s Birthday)', 'Memorial Day', 'Juneteenth', 'Independence Day', 'Labor Day', 'Columbus Day', 'Veterans Day', 'Thanksgiving Day', 'Christmas Day']::text[], '[{"key":"a1","display":"New Year’s Day","aliases":[]},{"key":"a2","display":"Martin Luther King, Jr. Day","aliases":["MLK Day","Martin Luther King Day"]},{"key":"a3","display":"Presidents Day (Washington’s Birthday)","aliases":["Presidents Day","Washington''s Birthday","Washington’s Birthday"]},{"key":"a4","display":"Memorial Day","aliases":[]},{"key":"a5","display":"Juneteenth","aliases":[]},{"key":"a6","display":"Independence Day","aliases":[]},{"key":"a7","display":"Labor Day","aliases":[]},{"key":"a8","display":"Columbus Day","aliases":[]},{"key":"a9","display":"Veterans Day","aliases":[]},{"key":"a10","display":"Thanksgiving Day","aliases":["Thanksgiving"]},{"key":"a11","display":"Christmas Day","aliases":["Christmas"]}]'::jsonb, '[["Texas Independence Day","Patriots’ Day","César Chávez Day"],["César Chávez Day","Confederate Memorial Day","Alaska Day"],["Alaska Day","Texas Independence Day","Patriots’ Day"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'The listed federal national holidays are the accepted set; the distractors are state or local observances, not national U.S. holidays.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 127, 1, ARRAY['A holiday to honor soldiers who died in military service']::text[], '[{"key":"a1","display":"A holiday to honor soldiers who died in military service","aliases":["holiday to honor soldiers who died in military service"]}]'::jsonb, '[["a holiday honoring all living veterans"],["a holiday celebrating independence from Britain"],["a holiday honoring the Constitution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Memorial Day honors service members who died in military service; Veterans Day honors people who served, and Independence Day marks independence.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft'),
  ('npa-practice-2026-10-28-v1', '2025', 128, 1, ARRAY['A holiday to honor people in the (U.S.) military', 'A holiday to honor people who have served (in the U.S. military)']::text[], '[{"key":"a1","display":"A holiday to honor people in the (U.S.) military","aliases":["A holiday to honor people in the military","A holiday to honor people in the U.S. military","holiday to honor people in the (U.S.) military"]},{"key":"a2","display":"A holiday to honor people who have served (in the U.S. military)","aliases":["A holiday to honor people who have served","A holiday to honor people who have served in the U.S. military","holiday to honor people who have served (in the U.S. military)"]}]'::jsonb, '[["a holiday solely for soldiers who died in service"],["a holiday celebrating independence from Britain"],["a holiday honoring the Constitution"]]'::jsonb, '{"answer_groups":"catalog","current_aliases":"catalog","distractors":"curated"}'::jsonb, 'Veterans Day honors people who serve or have served in the military; remembrance of those who died is Memorial Day.', ARRAY['https://www.uscis.gov/sites/default/files/document/questions-and-answers/2025-Civics-Test-128-Questions-and-Answers.pdf']::text[], 'draft')
on conflict (content_version, edition, question_number) do update set
